export default {"checked":"2026-11-11","copyright":"© Copyright 2010. National Governors Association Center for Best Practices and Council of Chief State School Officers. All rights reserved.","owner":"National Governors Association Center for Best Practices and Council of Chief State School Officers","license":"https://www.thecorestandards.org/public-license/","standards":[{"code":"RL.K.1","grade":"K","strand":"RL","section":"Key Ideas and Details:","description":"With prompting and support, ask and answer questions about key details in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.2","grade":"K","strand":"RL","section":"Key Ideas and Details:","description":"With prompting and support, retell familiar stories, including key details.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.3","grade":"K","strand":"RL","section":"Key Ideas and Details:","description":"With prompting and support, identify characters, settings, and major events in a story.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.4","grade":"K","strand":"RL","section":"Craft and Structure:","description":"Ask and answer questions about unknown words in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.5","grade":"K","strand":"RL","section":"Craft and Structure:","description":"Recognize common types of texts (e.g., storybooks, poems).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.6","grade":"K","strand":"RL","section":"Craft and Structure:","description":"With prompting and support, name the author and illustrator of a story and define the role of each in telling the story.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.7","grade":"K","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"With prompting and support, describe the relationship between illustrations and the story in which they appear (e.g., what moment in a story an illustration depicts).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.8","grade":"K","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.K.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":false},{"code":"RL.K.9","grade":"K","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"With prompting and support, compare and contrast the adventures and experiences of characters in familiar stories.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RL.K.10","grade":"K","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"Actively engage in group reading activities with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/K/","applicable":true},{"code":"RI.K.1","grade":"K","strand":"RI","section":"Key Ideas and Details:","description":"With prompting and support, ask and answer questions about key details in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.2","grade":"K","strand":"RI","section":"Key Ideas and Details:","description":"With prompting and support, identify the main topic and retell key details of a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.3","grade":"K","strand":"RI","section":"Key Ideas and Details:","description":"With prompting and support, describe the connection between two individuals, events, ideas, or pieces of information in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.4","grade":"K","strand":"RI","section":"Craft and Structure:","description":"With prompting and support, ask and answer questions about unknown words in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.5","grade":"K","strand":"RI","section":"Craft and Structure:","description":"Identify the front cover, back cover, and title page of a book.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.6","grade":"K","strand":"RI","section":"Craft and Structure:","description":"Name the author and illustrator of a text and define the role of each in presenting the ideas or information in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.7","grade":"K","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"With prompting and support, describe the relationship between illustrations and the text in which they appear (e.g., what person, place, thing, or idea in the text an illustration depicts).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.8","grade":"K","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"With prompting and support, identify the reasons an author gives to support points in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.9","grade":"K","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"With prompting and support, identify basic similarities in and differences between two texts on the same topic (e.g., in illustrations, descriptions, or procedures).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"RI.K.10","grade":"K","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"Actively engage in group reading activities with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/K/","applicable":true},{"code":"W.K.1","grade":"K","strand":"W","section":"Text Types and Purposes:","description":"Use a combination of drawing, dictating, and writing to compose opinion pieces in which they tell a reader the topic or the name of the book they are writing about and state an opinion or preference about the topic or book (e.g., My favorite book is…).","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.2","grade":"K","strand":"W","section":"Text Types and Purposes:","description":"Use a combination of drawing, dictating, and writing to compose informative/explanatory texts in which they name what they are writing about and supply some information about the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.3","grade":"K","strand":"W","section":"Text Types and Purposes:","description":"Use a combination of drawing, dictating, and writing to narrate a single event or several loosely linked events, tell about the events in the order in which they occurred, and provide a reaction to what happened.","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.4","grade":"K","strand":"W","section":"Production and Distribution of Writing:","description":"(W.K.4 begins in grade 3)","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.5","grade":"K","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, respond to questions and suggestions from peers and add details to strengthen writing as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.6","grade":"K","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, explore a variety of digital tools to produce and publish writing, including in collaboration with peers.","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.7","grade":"K","strand":"W","section":"Research to Build and Present Knowledge:","description":"Participate in shared research and writing projects (e.g., explore a number of books by a favorite author and express opinions about them).","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.8","grade":"K","strand":"W","section":"Research to Build and Present Knowledge:","description":"With guidance and support from adults, recall information from experiences or gather information from provided sources to answer a question.","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.9","grade":"K","strand":"W","section":"Research to Build and Present Knowledge:","description":"(W.K.9 begins in grade 4)","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"W.K.10","grade":"K","strand":"W","section":"Range of Writing:","description":"(W.K.10 begins in grade 3)","source":"https://www.thecorestandards.org/ELA-Literacy/W/K/","applicable":true},{"code":"SL.K.1","grade":"K","strand":"SL","section":"Comprehension and Collaboration:","description":"Participate in collaborative conversations with diverse partners about kindergarten topics and texts with peers and adults in small and larger groups.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.1.a","grade":"K","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow agreed-upon rules for discussions (e.g., listening to others and taking turns speaking about the topics and texts under discussion).","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.1.b","grade":"K","strand":"SL","section":"Comprehension and Collaboration:","description":"Continue a conversation through multiple exchanges.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.2","grade":"K","strand":"SL","section":"Comprehension and Collaboration:","description":"Confirm understanding of a text read aloud or information presented orally or through other media by asking and answering questions about key details and requesting clarification if something is not understood.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.3","grade":"K","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask and answer questions in order to seek help, get information, or clarify something that is not understood.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.4","grade":"K","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Describe familiar people, places, things, and events and, with prompting and support, provide additional detail.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.5","grade":"K","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Add drawings or other visual displays to descriptions as desired to provide additional detail.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"SL.K.6","grade":"K","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Speak audibly and express thoughts, feelings, and ideas clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/K/","applicable":true},{"code":"L.K.1","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.1.a","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Print many upper- and lowercase letters.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.1.b","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Use frequently occurring nouns and verbs.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.1.c","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Form regular plural nouns orally by adding /s/ or /es/ (e.g., dog, dogs; wish, wishes).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.1.d","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Understand and use question words (interrogatives) (e.g., who, what, where, when, why, how).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.1.e","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Use the most frequently occurring prepositions (e.g., to, from, in, out, on, off, for, of, by, with).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.1.f","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Produce and expand complete sentences in shared language activities.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.2","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.2.a","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Capitalize the first word in a sentence and the pronoun I","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.2.b","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Recognize and name end punctuation.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.2.c","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Write a letter or letters for most consonant and short-vowel sounds (phonemes).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.2.d","grade":"K","strand":"L","section":"Conventions of Standard English:","description":"Spell simple words phonetically, drawing on knowledge of sound-letter relationships.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.3","grade":"K","strand":"L","section":"Knowledge of Language:","description":"(L.K.3 begins in grade 2)","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.4","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on kindergarten reading and content.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.4.a","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify new meanings for familiar words and apply them accurately (e.g., knowing duck is a bird and learning the verb to duck).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.4.b","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use the most frequently occurring inflections and affixes (e.g., -ed, -s, re-, un-, pre-, -ful, -less) as a clue to the meaning of an unknown word.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.5","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"With guidance and support from adults, explore word relationships and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.5.a","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Sort common objects into categories (e.g., shapes, foods) to gain a sense of the concepts the categories represent.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.5.b","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of frequently occurring verbs and adjectives by relating them to their opposites (antonyms).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.5.c","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify real-life connections between words and their use (e.g., note places at school that are colorful).","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.5.d","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish shades of meaning among verbs describing the same general action (e.g., walk, march, strut, prance) by acting out the meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"L.K.6","grade":"K","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use words and phrases acquired through conversations, reading and being read to, and responding to texts.","source":"https://www.thecorestandards.org/ELA-Literacy/L/K/","applicable":true},{"code":"RF.K.1","grade":"K","strand":"RF","section":"Print Concepts:","description":"Demonstrate understanding of the organization and basic features of print.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.1.a","grade":"K","strand":"RF","section":"Print Concepts:","description":"Follow words from left to right, top to bottom, and page by page.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.1.b","grade":"K","strand":"RF","section":"Print Concepts:","description":"Recognize that spoken words are represented in written language by specific sequences of letters.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.1.c","grade":"K","strand":"RF","section":"Print Concepts:","description":"Understand that words are separated by spaces in print.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.1.d","grade":"K","strand":"RF","section":"Print Concepts:","description":"Recognize and name all upper- and lowercase letters of the alphabet.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.2","grade":"K","strand":"RF","section":"Phonological Awareness:","description":"Demonstrate understanding of spoken words, syllables, and sounds (phonemes).","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.2.a","grade":"K","strand":"RF","section":"Phonological Awareness:","description":"Recognize and produce rhyming words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.2.b","grade":"K","strand":"RF","section":"Phonological Awareness:","description":"Count, pronounce, blend, and segment syllables in spoken words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.2.c","grade":"K","strand":"RF","section":"Phonological Awareness:","description":"Blend and segment onsets and rimes of single-syllable spoken words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.2.d","grade":"K","strand":"RF","section":"Phonological Awareness:","description":"Isolate and pronounce the initial, medial vowel, and final sounds (phonemes) in three-phoneme (consonant-vowel-consonant, or CVC) words.^{1} (This does not include CVCs ending with /l/, /r/, or /x/.)","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.2.e","grade":"K","strand":"RF","section":"Phonological Awareness:","description":"Add or substitute individual sounds (phonemes) in simple, one-syllable words to make new words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.3","grade":"K","strand":"RF","section":"Phonics and Word Recognition:","description":"Know and apply grade-level phonics and word analysis skills in decoding words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.3.a","grade":"K","strand":"RF","section":"Phonics and Word Recognition:","description":"Demonstrate basic knowledge of one-to-one letter-sound correspondences by producing the primary sound or many of the most frequent sounds for each consonant.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.3.b","grade":"K","strand":"RF","section":"Phonics and Word Recognition:","description":"Associate the long and short sounds with the common spellings (graphemes) for the five major vowels.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.3.c","grade":"K","strand":"RF","section":"Phonics and Word Recognition:","description":"Read common high-frequency words by sight (e.g., the, of, to, you, she, my, is, are, do, does).","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.3.d","grade":"K","strand":"RF","section":"Phonics and Word Recognition:","description":"Distinguish between similarly spelled words by identifying the sounds of the letters that differ.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RF.K.4","grade":"K","strand":"RF","section":"Fluency:","description":"Read emergent-reader texts with purpose and understanding. ^{1} Words, syllables, or phonemes written in /slashes/refer to their pronunciations or phonology. Thus,/CVC/ is a word with three phonemes regardless of the number of letters in the spelling of the word.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/K/","applicable":true},{"code":"RL.1.1","grade":"1","strand":"RL","section":"Key Ideas and Details:","description":"Ask and answer questions about key details in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.2","grade":"1","strand":"RL","section":"Key Ideas and Details:","description":"Retell stories, including key details, and demonstrate understanding of their central message or lesson.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.3","grade":"1","strand":"RL","section":"Key Ideas and Details:","description":"Describe characters, settings, and major events in a story, using key details.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.4","grade":"1","strand":"RL","section":"Craft and Structure:","description":"Identify words and phrases in stories or poems that suggest feelings or appeal to the senses.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.5","grade":"1","strand":"RL","section":"Craft and Structure:","description":"Explain major differences between books that tell stories and books that give information, drawing on a wide reading of a range of text types.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.6","grade":"1","strand":"RL","section":"Craft and Structure:","description":"Identify who is telling the story at various points in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.7","grade":"1","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Use illustrations and details in a story to describe its characters, setting, or events.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.8","grade":"1","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.1.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":false},{"code":"RL.1.9","grade":"1","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the adventures and experiences of characters in stories.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RL.1.10","grade":"1","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"With prompting and support, read prose and poetry of appropriate complexity for grade 1.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/1/","applicable":true},{"code":"RI.1.1","grade":"1","strand":"RI","section":"Key Ideas and Details:","description":"Ask and answer questions about key details in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.2","grade":"1","strand":"RI","section":"Key Ideas and Details:","description":"Identify the main topic and retell key details of a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.3","grade":"1","strand":"RI","section":"Key Ideas and Details:","description":"Describe the connection between two individuals, events, ideas, or pieces of information in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.4","grade":"1","strand":"RI","section":"Craft and Structure:","description":"Ask and answer questions to help determine or clarify the meaning of words and phrases in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.5","grade":"1","strand":"RI","section":"Craft and Structure:","description":"Know and use various text features (e.g., headings, tables of contents, glossaries, electronic menus, icons) to locate key facts or information in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.6","grade":"1","strand":"RI","section":"Craft and Structure:","description":"Distinguish between information provided by pictures or other illustrations and information provided by the words in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.7","grade":"1","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Use the illustrations and details in a text to describe its key ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.8","grade":"1","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Identify the reasons an author gives to support points in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.9","grade":"1","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Identify basic similarities in and differences between two texts on the same topic (e.g., in illustrations, descriptions, or procedures).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"RI.1.10","grade":"1","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"With prompting and support, read informational texts appropriately complex for grade 1.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/1/","applicable":true},{"code":"W.1.1","grade":"1","strand":"W","section":"Text Types and Purposes:","description":"Write opinion pieces in which they introduce the topic or name the book they are writing about, state an opinion, supply a reason for the opinion, and provide some sense of closure.","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.2","grade":"1","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts in which they name a topic, supply some facts about the topic, and provide some sense of closure.","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.3","grade":"1","strand":"W","section":"Text Types and Purposes:","description":"Write narratives in which they recount two or more appropriately sequenced events, include some details regarding what happened, use temporal words to signal event order, and provide some sense of closure.","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.4","grade":"1","strand":"W","section":"Production and Distribution of Writing:","description":"(W.1.4 begins in grade 3)","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.5","grade":"1","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, focus on a topic, respond to questions and suggestions from peers, and add details to strengthen writing as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.6","grade":"1","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, use a variety of digital tools to produce and publish writing, including in collaboration with peers.","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.7","grade":"1","strand":"W","section":"Research to Build and Present Knowledge:","description":"Participate in shared research and writing projects (e.g., explore a number of \"how-to\" books on a given topic and use them to write a sequence of instructions).","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.8","grade":"1","strand":"W","section":"Research to Build and Present Knowledge:","description":"With guidance and support from adults, recall information from experiences or gather information from provided sources to answer a question.","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.9","grade":"1","strand":"W","section":"Research to Build and Present Knowledge:","description":"(W.1.9 begins in grade 4)","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"W.1.10","grade":"1","strand":"W","section":"Range of Writing:","description":"(W.1.10 begins in grade 3)","source":"https://www.thecorestandards.org/ELA-Literacy/W/1/","applicable":true},{"code":"SL.1.1","grade":"1","strand":"SL","section":"Comprehension and Collaboration:","description":"Participate in collaborative conversations with diverse partners about grade 1 topics and texts with peers and adults in small and larger groups.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.1.a","grade":"1","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow agreed-upon rules for discussions (e.g., listening to others with care, speaking one at a time about the topics and texts under discussion).","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.1.b","grade":"1","strand":"SL","section":"Comprehension and Collaboration:","description":"Build on others' talk in conversations by responding to the comments of others through multiple exchanges.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.1.c","grade":"1","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask questions to clear up any confusion about the topics and texts under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.2","grade":"1","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask and answer questions about key details in a text read aloud or information presented orally or through other media.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.3","grade":"1","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask and answer questions about what a speaker says in order to gather additional information or clarify something that is not understood.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.4","grade":"1","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Describe people, places, things, and events with relevant details, expressing ideas and feelings clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.5","grade":"1","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Add drawings or other visual displays to descriptions when appropriate to clarify ideas, thoughts, and feelings.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"SL.1.6","grade":"1","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Produce complete sentences when appropriate to task and situation. (See grade 1 Language standards 1 and 3 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/1/","applicable":true},{"code":"L.1.1","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.a","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Print all upper- and lowercase letters.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.b","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use common, proper, and possessive nouns.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.c","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use singular and plural nouns with matching verbs in basic sentences (e.g., He hops; We hop).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.d","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use personal, possessive, and indefinite pronouns (e.g., I, me, my; they, them, their, anyone, everything).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.e","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use verbs to convey a sense of past, present, and future (e.g., Yesterday I walked home; Today I walk home; Tomorrow I will walk home).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.f","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use frequently occurring adjectives.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.g","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use frequently occurring conjunctions (e.g., and, but, or, so, because).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.h","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use determiners (e.g., articles, demonstratives).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.i","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use frequently occurring prepositions (e.g., during, beyond, toward).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.1.j","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Produce and expand complete simple and compound declarative, interrogative, imperative, and exclamatory sentences in response to prompts.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.2","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.2.a","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Capitalize dates and names of people.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.2.b","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use end punctuation for sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.2.c","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use commas in dates and to separate single words in a series.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.2.d","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Use conventional spelling for words with common spelling patterns and for frequently occurring irregular words.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.2.e","grade":"1","strand":"L","section":"Conventions of Standard English:","description":"Spell untaught words phonetically, drawing on phonemic awareness and spelling conventions.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.3","grade":"1","strand":"L","section":"Knowledge of Language:","description":"(L.1.3 begins in grade 2)","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.4","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grade 1 reading and content, choosing flexibly from an array of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.4.a","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use sentence-level context as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.4.b","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use frequently occurring affixes as a clue to the meaning of a word.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.4.c","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify frequently occurring root words (e.g., look) and their inflectional forms (e.g., looks, looked, looking).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.5","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"With guidance and support from adults, demonstrate understanding of word relationships and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.5.a","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Sort words into categories (e.g., colors, clothing) to gain a sense of the concepts the categories represent.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.5.b","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Define words by category and by one or more key attributes (e.g., a duck is a bird that swims; a tiger is a large cat with stripes).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.5.c","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify real-life connections between words and their use (e.g., note places at home that are cozy).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.5.d","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish shades of meaning among verbs differing in manner (e.g., look, peek, glance, stare, glare, scowl) and adjectives differing in intensity (e.g., large, gigantic) by defining or choosing them or by acting out the meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"L.1.6","grade":"1","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use words and phrases acquired through conversations, reading and being read to, and responding to texts, including using frequently occurring conjunctions to signal simple relationships (e.g., because).","source":"https://www.thecorestandards.org/ELA-Literacy/L/1/","applicable":true},{"code":"RF.1.1","grade":"1","strand":"RF","section":"Print Concepts:","description":"Demonstrate understanding of the organization and basic features of print.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.1.a","grade":"1","strand":"RF","section":"Print Concepts:","description":"Recognize the distinguishing features of a sentence (e.g., first word, capitalization, ending punctuation).","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.2","grade":"1","strand":"RF","section":"Phonological Awareness:","description":"Demonstrate understanding of spoken words, syllables, and sounds (phonemes).","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.2.a","grade":"1","strand":"RF","section":"Phonological Awareness:","description":"Distinguish long from short vowel sounds in spoken single-syllable words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.2.b","grade":"1","strand":"RF","section":"Phonological Awareness:","description":"Orally produce single-syllable words by blending sounds (phonemes), including consonant blends.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.2.c","grade":"1","strand":"RF","section":"Phonological Awareness:","description":"Isolate and pronounce initial, medial vowel, and final sounds (phonemes) in spoken single-syllable words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.2.d","grade":"1","strand":"RF","section":"Phonological Awareness:","description":"Segment spoken single-syllable words into their complete sequence of individual sounds (phonemes).","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Know and apply grade-level phonics and word analysis skills in decoding words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.a","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Know the spelling-sound correspondences for common consonant digraphs.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.b","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Decode regularly spelled one-syllable words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.c","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Know final -e and common vowel team conventions for representing long vowel sounds.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.d","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Use knowledge that every syllable must have a vowel sound to determine the number of syllables in a printed word.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.e","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Decode two-syllable words following basic patterns by breaking the words into syllables.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.f","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Read words with inflectional endings.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.3.g","grade":"1","strand":"RF","section":"Phonics and Word Recognition:","description":"Recognize and read grade-appropriate irregularly spelled words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.4","grade":"1","strand":"RF","section":"Fluency:","description":"Read with sufficient accuracy and fluency to support comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.4.a","grade":"1","strand":"RF","section":"Fluency:","description":"Read grade-level text with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.4.b","grade":"1","strand":"RF","section":"Fluency:","description":"Read grade-level text orally with accuracy, appropriate rate, and expression on successive readings.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RF.1.4.c","grade":"1","strand":"RF","section":"Fluency:","description":"Use context to confirm or self-correct word recognition and understanding, rereading as necessary.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/1/","applicable":true},{"code":"RL.2.1","grade":"2","strand":"RL","section":"Key Ideas and Details:","description":"Ask and answer such questions as who, what, where, when, why, and how to demonstrate understanding of key details in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.2","grade":"2","strand":"RL","section":"Key Ideas and Details:","description":"Recount stories, including fables and folktales from diverse cultures, and determine their central message, lesson, or moral.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.3","grade":"2","strand":"RL","section":"Key Ideas and Details:","description":"Describe how characters in a story respond to major events and challenges.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.4","grade":"2","strand":"RL","section":"Craft and Structure:","description":"Describe how words and phrases (e.g., regular beats, alliteration, rhymes, repeated lines) supply rhythm and meaning in a story, poem, or song.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.5","grade":"2","strand":"RL","section":"Craft and Structure:","description":"Describe the overall structure of a story, including describing how the beginning introduces the story and the ending concludes the action.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.6","grade":"2","strand":"RL","section":"Craft and Structure:","description":"Acknowledge differences in the points of view of characters, including by speaking in a different voice for each character when reading dialogue aloud.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.7","grade":"2","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Use information gained from the illustrations and words in a print or digital text to demonstrate understanding of its characters, setting, or plot.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.8","grade":"2","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.2.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":false},{"code":"RL.2.9","grade":"2","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast two or more versions of the same story (e.g., Cinderella stories) by different authors or from different cultures.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RL.2.10","grade":"2","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories and poetry, in the grades 2-3 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/2/","applicable":true},{"code":"RI.2.1","grade":"2","strand":"RI","section":"Key Ideas and Details:","description":"Ask and answer such questions as who, what, where, when, why, and how to demonstrate understanding of key details in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.2","grade":"2","strand":"RI","section":"Key Ideas and Details:","description":"Identify the main topic of a multiparagraph text as well as the focus of specific paragraphs within the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.3","grade":"2","strand":"RI","section":"Key Ideas and Details:","description":"Describe the connection between a series of historical events, scientific ideas or concepts, or steps in technical procedures in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.4","grade":"2","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of words and phrases in a text relevant to a grade 2 topic or subject area.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.5","grade":"2","strand":"RI","section":"Craft and Structure:","description":"Know and use various text features (e.g., captions, bold print, subheadings, glossaries, indexes, electronic menus, icons) to locate key facts or information in a text efficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.6","grade":"2","strand":"RI","section":"Craft and Structure:","description":"Identify the main purpose of a text, including what the author wants to answer, explain, or describe.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.7","grade":"2","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Explain how specific images (e.g., a diagram showing how a machine works) contribute to and clarify a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.8","grade":"2","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Describe how reasons support specific points the author makes in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.9","grade":"2","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the most important points presented by two texts on the same topic.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"RI.2.10","grade":"2","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of year, read and comprehend informational texts, including history/social studies, science, and technical texts, in the grades 2-3 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/2/","applicable":true},{"code":"W.2.1","grade":"2","strand":"W","section":"Text Types and Purposes:","description":"Write opinion pieces in which they introduce the topic or book they are writing about, state an opinion, supply reasons that support the opinion, use linking words (e.g., because, and, also) to connect opinion and reasons, and provide a concluding statement or section.","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.2","grade":"2","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts in which they introduce a topic, use facts and definitions to develop points, and provide a concluding statement or section.","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.3","grade":"2","strand":"W","section":"Text Types and Purposes:","description":"Write narratives in which they recount a well-elaborated event or short sequence of events, include details to describe actions, thoughts, and feelings, use temporal words to signal event order, and provide a sense of closure.","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.4","grade":"2","strand":"W","section":"Production and Distribution of Writing:","description":"(W.2.4 begins in grade 3)","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.5","grade":"2","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults and peers, focus on a topic and strengthen writing as needed by revising and editing.","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.6","grade":"2","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, use a variety of digital tools to produce and publish writing, including in collaboration with peers.","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.7","grade":"2","strand":"W","section":"Research to Build and Present Knowledge:","description":"Participate in shared research and writing projects (e.g., read a number of books on a single topic to produce a report; record science observations).","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.8","grade":"2","strand":"W","section":"Research to Build and Present Knowledge:","description":"Recall information from experiences or gather information from provided sources to answer a question.","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.9","grade":"2","strand":"W","section":"Research to Build and Present Knowledge:","description":"(W.2.9 begins in grade 4)","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"W.2.10","grade":"2","strand":"W","section":"Range of Writing:","description":"(W.2.10 begins in grade 3)","source":"https://www.thecorestandards.org/ELA-Literacy/W/2/","applicable":true},{"code":"SL.2.1","grade":"2","strand":"SL","section":"Comprehension and Collaboration:","description":"Participate in collaborative conversations with diverse partners about grade 2 topics and texts with peers and adults in small and larger groups.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.1.a","grade":"2","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow agreed-upon rules for discussions (e.g., gaining the floor in respectful ways, listening to others with care, speaking one at a time about the topics and texts under discussion).","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.1.b","grade":"2","strand":"SL","section":"Comprehension and Collaboration:","description":"Build on others' talk in conversations by linking their comments to the remarks of others.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.1.c","grade":"2","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask for clarification and further explanation as needed about the topics and texts under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.2","grade":"2","strand":"SL","section":"Comprehension and Collaboration:","description":"Recount or describe key ideas or details from a text read aloud or information presented orally or through other media.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.3","grade":"2","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask and answer questions about what a speaker says in order to clarify comprehension, gather additional information, or deepen understanding of a topic or issue.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.4","grade":"2","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Tell a story or recount an experience with appropriate facts and relevant, descriptive details, speaking audibly in coherent sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.5","grade":"2","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Create audio recordings of stories or poems; add drawings or other visual displays to stories or recounts of experiences when appropriate to clarify ideas, thoughts, and feelings.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"SL.2.6","grade":"2","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Produce complete sentences when appropriate to task and situation in order to provide requested detail or clarification. (See grade 2 Language standards 1 and 3 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/2/","applicable":true},{"code":"L.2.1","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.1.a","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Use collective nouns (e.g., group).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.1.b","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Form and use frequently occurring irregular plural nouns (e.g., feet, children, teeth, mice, fish).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.1.c","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Use reflexive pronouns (e.g., myself, ourselves).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.1.d","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Form and use the past tense of frequently occurring irregular verbs (e.g., sat, hid, told).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.1.e","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Use adjectives and adverbs, and choose between them depending on what is to be modified.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.1.f","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Produce, expand, and rearrange complete simple and compound sentences (e.g., The boy watched the movie; The little boy watched the movie; The action movie was watched by the little boy).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.2","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.2.a","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Capitalize holidays, product names, and geographic names.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.2.b","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Use commas in greetings and closings of letters.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.2.c","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Use an apostrophe to form contractions and frequently occurring possessives.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.2.d","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Generalize learned spelling patterns when writing words (e.g., cage → badge; boy → boil).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.2.e","grade":"2","strand":"L","section":"Conventions of Standard English:","description":"Consult reference materials, including beginning dictionaries, as needed to check and correct spellings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.3","grade":"2","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.3.a","grade":"2","strand":"L","section":"Knowledge of Language:","description":"Compare formal and informal uses of English","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.4","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grade 2 reading and content, choosing flexibly from an array of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.4.a","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use sentence-level context as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.4.b","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine the meaning of the new word formed when a known prefix is added to a known word (e.g., happy/unhappy, tell/retell).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.4.c","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use a known root word as a clue to the meaning of an unknown word with the same root (e.g., addition, additional).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.4.d","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use knowledge of the meaning of individual words to predict the meaning of compound words (e.g., birdhouse, lighthouse, housefly; bookshelf, notebook, bookmark).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.4.e","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use glossaries and beginning dictionaries, both print and digital, to determine or clarify the meaning of words and phrases.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.5","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of word relationships and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.5.a","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify real-life connections between words and their use (e.g., describe foods that are spicy or juicy).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.5.b","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish shades of meaning among closely related verbs (e.g., toss, throw, hurl) and closely related adjectives (e.g., thin, slender, skinny, scrawny).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"L.2.6","grade":"2","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use words and phrases acquired through conversations, reading and being read to, and responding to texts, including using adjectives and adverbs to describe (e.g., When other kids are happy that makes me happy).","source":"https://www.thecorestandards.org/ELA-Literacy/L/2/","applicable":true},{"code":"RF.2.3","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Know and apply grade-level phonics and word analysis skills in decoding words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.3.a","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Distinguish long and short vowels when reading regularly spelled one-syllable words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.3.b","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Know spelling-sound correspondences for additional common vowel teams.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.3.c","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Decode regularly spelled two-syllable words with long vowels.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.3.d","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Decode words with common prefixes and suffixes.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.3.e","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Identify words with inconsistent but common spelling-sound correspondences.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.3.f","grade":"2","strand":"RF","section":"Phonics and Word Recognition:","description":"Recognize and read grade-appropriate irregularly spelled words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.4","grade":"2","strand":"RF","section":"Fluency:","description":"Read with sufficient accuracy and fluency to support comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.4.a","grade":"2","strand":"RF","section":"Fluency:","description":"Read grade-level text with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.4.b","grade":"2","strand":"RF","section":"Fluency:","description":"Read grade-level text orally with accuracy, appropriate rate, and expression on successive readings.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RF.2.4.c","grade":"2","strand":"RF","section":"Fluency:","description":"Use context to confirm or self-correct word recognition and understanding, rereading as necessary.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/2/","applicable":true},{"code":"RL.3.1","grade":"3","strand":"RL","section":"Key Ideas and Details:","description":"Ask and answer questions to demonstrate understanding of a text, referring explicitly to the text as the basis for the answers.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.2","grade":"3","strand":"RL","section":"Key Ideas and Details:","description":"Recount stories, including fables, folktales, and myths from diverse cultures; determine the central message, lesson, or moral and explain how it is conveyed through key details in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.3","grade":"3","strand":"RL","section":"Key Ideas and Details:","description":"Describe characters in a story (e.g., their traits, motivations, or feelings) and explain how their actions contribute to the sequence of events","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.4","grade":"3","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, distinguishing literal from nonliteral language.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.5","grade":"3","strand":"RL","section":"Craft and Structure:","description":"Refer to parts of stories, dramas, and poems when writing or speaking about a text, using terms such as chapter, scene, and stanza; describe how each successive part builds on earlier sections.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.6","grade":"3","strand":"RL","section":"Craft and Structure:","description":"Distinguish their own point of view from that of the narrator or those of the characters.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.7","grade":"3","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Explain how specific aspects of a text's illustrations contribute to what is conveyed by the words in a story (e.g., create mood, emphasize aspects of a character or setting)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.8","grade":"3","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.3.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":false},{"code":"RL.3.9","grade":"3","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the themes, settings, and plots of stories written by the same author about the same or similar characters (e.g., in books from a series)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RL.3.10","grade":"3","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories, dramas, and poetry, at the high end of the grades 2-3 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/3/","applicable":true},{"code":"RI.3.1","grade":"3","strand":"RI","section":"Key Ideas and Details:","description":"Ask and answer questions to demonstrate understanding of a text, referring explicitly to the text as the basis for the answers.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.2","grade":"3","strand":"RI","section":"Key Ideas and Details:","description":"Determine the main idea of a text; recount the key details and explain how they support the main idea.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.3","grade":"3","strand":"RI","section":"Key Ideas and Details:","description":"Describe the relationship between a series of historical events, scientific ideas or concepts, or steps in technical procedures in a text, using language that pertains to time, sequence, and cause/effect.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.4","grade":"3","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of general academic and domain-specific words and phrases in a text relevant to a grade 3 topic or subject area.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.5","grade":"3","strand":"RI","section":"Craft and Structure:","description":"Use text features and search tools (e.g., key words, sidebars, hyperlinks) to locate information relevant to a given topic efficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.6","grade":"3","strand":"RI","section":"Craft and Structure:","description":"Distinguish their own point of view from that of the author of a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.7","grade":"3","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Use information gained from illustrations (e.g., maps, photographs) and the words in a text to demonstrate understanding of the text (e.g., where, when, why, and how key events occur).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.8","grade":"3","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Describe the logical connection between particular sentences and paragraphs in a text (e.g., comparison, cause/effect, first/second/third in a sequence).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.9","grade":"3","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the most important points and key details presented in two texts on the same topic.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"RI.3.10","grade":"3","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend informational texts, including history/social studies, science, and technical texts, at the high end of the grades 2-3 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/3/","applicable":true},{"code":"W.3.1","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Write opinion pieces on topics or texts, supporting a point of view with reasons.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.1.a","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Introduce the topic or text they are writing about, state an opinion, and create an organizational structure that lists reasons.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.1.b","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Provide reasons that support the opinion.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.1.c","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Use linking words and phrases (e.g., because, therefore, since, for example) to connect opinion and reasons.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.1.d","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.2","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine a topic and convey ideas and information clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.2.a","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic and group related information together; include illustrations when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.2.b","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with facts, definitions, and details.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.2.c","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Use linking words and phrases (e.g., also, another, and, more, but) to connect ideas within categories of information.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.2.d","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.3","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, descriptive details, and clear event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.3.a","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Establish a situation and introduce a narrator and/or characters; organize an event sequence that unfolds naturally.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.3.b","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Use dialogue and descriptions of actions, thoughts, and feelings to develop experiences and events or show the response of characters to situations.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.3.c","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Use temporal words and phrases to signal event order.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.3.d","grade":"3","strand":"W","section":"Text Types and Purposes:","description":"Provide a sense of closure.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.4","grade":"3","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, produce writing in which the development and organization are appropriate to task and purpose. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.5","grade":"3","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, and editing. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grade 3 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.6","grade":"3","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from adults, use technology to produce and publish writing (using keyboarding skills) as well as to interact and collaborate with others.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.7","grade":"3","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects that build knowledge about a topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.8","grade":"3","strand":"W","section":"Research to Build and Present Knowledge:","description":"Recall information from experiences or gather information from print and digital sources; take brief notes on sources and sort evidence into provided categories.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.9","grade":"3","strand":"W","section":"Research to Build and Present Knowledge:","description":"(W.3.9 begins in grade 4)","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"W.3.10","grade":"3","strand":"W","section":"Range of Writing:","description":"Write routinely over extended time frames (time for research, reflection, and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/3/","applicable":true},{"code":"SL.3.1","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Engage effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grade 3 topics and texts, building on others' ideas and expressing their own clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.1.a","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read or studied required material; explicitly draw on that preparation and other information known about the topic to explore ideas under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.1.b","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow agreed-upon rules for discussions (e.g., gaining the floor in respectful ways, listening to others with care, speaking one at a time about the topics and texts under discussion).","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.1.c","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask questions to check understanding of information presented, stay on topic, and link their comments to the remarks of others.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.1.d","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Explain their own ideas and understanding in light of the discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.2","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Determine the main ideas and supporting details of a text read aloud or information presented in diverse media and formats, including visually, quantitatively, and orally.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.3","grade":"3","strand":"SL","section":"Comprehension and Collaboration:","description":"Ask and answer questions about information from a speaker, offering appropriate elaboration and detail.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.4","grade":"3","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Report on a topic or text, tell a story, or recount an experience with appropriate facts and relevant, descriptive details, speaking clearly at an understandable pace.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.5","grade":"3","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Create engaging audio recordings of stories or poems that demonstrate fluid reading at an understandable pace; add visual displays when appropriate to emphasize or enhance certain facts or details.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"SL.3.6","grade":"3","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Speak in complete sentences when appropriate to task and situation in order to provide requested detail or clarification. (See grade 3 Language standards 1 and 3 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/3/","applicable":true},{"code":"L.3.1","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.a","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Explain the function of nouns, pronouns, verbs, adjectives, and adverbs in general and their functions in particular sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.b","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Form and use regular and irregular plural nouns.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.c","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Use abstract nouns (e.g., childhood).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.d","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Form and use regular and irregular verbs.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.e","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Form and use the simple (e.g., I walked; I walk; I will walk) verb tenses.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.f","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Ensure subject-verb and pronoun-antecedent agreement.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.g","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Form and use comparative and superlative adjectives and adverbs, and choose between them depending on what is to be modified.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.h","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Use coordinating and subordinating conjunctions.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.1.i","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Produce simple, compound, and complex sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.a","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Capitalize appropriate words in titles.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.b","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Use commas in addresses.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.c","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Use commas and quotation marks in dialogue.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.d","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Form and use possessives.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.e","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Use conventional spelling for high-frequency and other studied words and for adding suffixes to base words (e.g., sitting, smiled, cries, happiness).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.f","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Use spelling patterns and generalizations (e.g., word families, position-based spellings, syllable patterns, ending rules, meaningful word parts) in writing words.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.2.g","grade":"3","strand":"L","section":"Conventions of Standard English:","description":"Consult reference materials, including beginning dictionaries, as needed to check and correct spellings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.3","grade":"3","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.3.a","grade":"3","strand":"L","section":"Knowledge of Language:","description":"Choose words and phrases for effect.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.3.b","grade":"3","strand":"L","section":"Knowledge of Language:","description":"Recognize and observe differences between the conventions of spoken and written standard English.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.4","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning word and phrases based on grade 3 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.4.a","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use sentence-level context as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.4.b","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine the meaning of the new word formed when a known affix is added to a known word (e.g., agreeable/disagreeable, comfortable/uncomfortable, care/careless, heat/preheat).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.4.c","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use a known root word as a clue to the meaning of an unknown word with the same root (e.g., company, companion).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.4.d","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use glossaries or beginning dictionaries, both print and digital, to determine or clarify the precise meaning of key words and phrases.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.5","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.5.a","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish the literal and nonliteral meanings of words and phrases in context (e.g., take steps).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.5.b","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify real-life connections between words and their use (e.g., describe people who are friendly or helpful).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.5.c","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish shades of meaning among related words that describe states of mind or degrees of certainty (e.g., knew, believed, suspected, heard, wondered).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"L.3.6","grade":"3","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately grade-appropriate conversational, general academic, and domain-specific words and phrases, including those that signal spatial and temporal relationships (e.g., After dinner that night we went looking for them).","source":"https://www.thecorestandards.org/ELA-Literacy/L/3/","applicable":true},{"code":"RF.3.3","grade":"3","strand":"RF","section":"Phonics and Word Recognition:","description":"Know and apply grade-level phonics and word analysis skills in decoding words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.3.a","grade":"3","strand":"RF","section":"Phonics and Word Recognition:","description":"Identify and know the meaning of the most common prefixes and derivational suffixes.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.3.b","grade":"3","strand":"RF","section":"Phonics and Word Recognition:","description":"Decode words with common Latin suffixes.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.3.c","grade":"3","strand":"RF","section":"Phonics and Word Recognition:","description":"Decode multisyllable words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.3.d","grade":"3","strand":"RF","section":"Phonics and Word Recognition:","description":"Read grade-appropriate irregularly spelled words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.4","grade":"3","strand":"RF","section":"Fluency:","description":"Read with sufficient accuracy and fluency to support comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.4.a","grade":"3","strand":"RF","section":"Fluency:","description":"Read grade-level text with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.4.b","grade":"3","strand":"RF","section":"Fluency:","description":"Read grade-level prose and poetry orally with accuracy, appropriate rate, and expression on successive readings.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RF.3.4.c","grade":"3","strand":"RF","section":"Fluency:","description":"Use context to confirm or self-correct word recognition and understanding, rereading as necessary.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/3/","applicable":true},{"code":"RL.4.1","grade":"4","strand":"RL","section":"Key Ideas and Details:","description":"Refer to details and examples in a text when explaining what the text says explicitly and when drawing inferences from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.2","grade":"4","strand":"RL","section":"Key Ideas and Details:","description":"Determine a theme of a story, drama, or poem from details in the text; summarize the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.3","grade":"4","strand":"RL","section":"Key Ideas and Details:","description":"Describe in depth a character, setting, or event in a story or drama, drawing on specific details in the text (e.g., a character's thoughts, words, or actions).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.4","grade":"4","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including those that allude to significant characters found in mythology (e.g., Herculean).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.5","grade":"4","strand":"RL","section":"Craft and Structure:","description":"Explain major differences between poems, drama, and prose, and refer to the structural elements of poems (e.g., verse, rhythm, meter) and drama (e.g., casts of characters, settings, descriptions, dialogue, stage directions) when writing or speaking about a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.6","grade":"4","strand":"RL","section":"Craft and Structure:","description":"Compare and contrast the point of view from which different stories are narrated, including the difference between first- and third-person narrations.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.7","grade":"4","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Make connections between the text of a story or drama and a visual or oral presentation of the text, identifying where each version reflects specific descriptions and directions in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.8","grade":"4","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.4.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":false},{"code":"RL.4.9","grade":"4","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the treatment of similar themes and topics (e.g., opposition of good and evil) and patterns of events (e.g., the quest) in stories, myths, and traditional literature from different cultures.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RL.4.10","grade":"4","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories, dramas, and poetry, in the grades 4-5 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/4/","applicable":true},{"code":"RI.4.1","grade":"4","strand":"RI","section":"Key Ideas and Details:","description":"Refer to details and examples in a text when explaining what the text says explicitly and when drawing inferences from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.2","grade":"4","strand":"RI","section":"Key Ideas and Details:","description":"Determine the main idea of a text and explain how it is supported by key details; summarize the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.3","grade":"4","strand":"RI","section":"Key Ideas and Details:","description":"Explain events, procedures, ideas, or concepts in a historical, scientific, or technical text, including what happened and why, based on specific information in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.4","grade":"4","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of general academic and domain-specific words or phrases in a text relevant to a grade 4 topic or subject area.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.5","grade":"4","strand":"RI","section":"Craft and Structure:","description":"Describe the overall structure (e.g., chronology, comparison, cause/effect, problem/solution) of events, ideas, concepts, or information in a text or part of a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.6","grade":"4","strand":"RI","section":"Craft and Structure:","description":"Compare and contrast a firsthand and secondhand account of the same event or topic; describe the differences in focus and the information provided.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.7","grade":"4","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Interpret information presented visually, orally, or quantitatively (e.g., in charts, graphs, diagrams, time lines, animations, or interactive elements on Web pages) and explain how the information contributes to an understanding of the text in which it appears.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.8","grade":"4","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Explain how an author uses reasons and evidence to support particular points in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.9","grade":"4","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Integrate information from two texts on the same topic in order to write or speak about the subject knowledgeably.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"RI.4.10","grade":"4","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of year, read and comprehend informational texts, including history/social studies, science, and technical texts, in the grades 4-5 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/4/","applicable":true},{"code":"W.4.1","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Write opinion pieces on topics or texts, supporting a point of view with reasons and information.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.1.a","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic or text clearly, state an opinion, and create an organizational structure in which related ideas are grouped to support the writer's purpose.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.1.b","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Provide reasons that are supported by facts and details.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.1.c","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Link opinion and reasons using words and phrases (e.g., for instance, in order to, in addition).","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.1.d","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section related to the opinion presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.2","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine a topic and convey ideas and information clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.2.a","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic clearly and group related information in paragraphs and sections; include formatting (e.g., headings), illustrations, and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.2.b","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with facts, definitions, concrete details, quotations, or other information and examples related to the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.2.c","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Link ideas within categories of information using words and phrases (e.g., another, for example, also, because).","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.2.d","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to inform about or explain the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.2.e","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section related to the information or explanation presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.3","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, descriptive details, and clear event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.3.a","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Orient the reader by establishing a situation and introducing a narrator and/or characters; organize an event sequence that unfolds naturally.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.3.b","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Use dialogue and description to develop experiences and events or show the responses of characters to situations.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.3.c","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of transitional words and phrases to manage the sequence of events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.3.d","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Use concrete words and phrases and sensory details to convey experiences and events precisely.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.3.e","grade":"4","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from the narrated experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.4","grade":"4","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development and organization are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.5","grade":"4","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, and editing. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grade 4 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.6","grade":"4","strand":"W","section":"Production and Distribution of Writing:","description":"With some guidance and support from adults, use technology, including the Internet, to produce and publish writing as well as to interact and collaborate with others; demonstrate sufficient command of keyboarding skills to type a minimum of one page in a single sitting.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.7","grade":"4","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects that build knowledge through investigation of different aspects of a topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.8","grade":"4","strand":"W","section":"Research to Build and Present Knowledge:","description":"Recall relevant information from experiences or gather relevant information from print and digital sources; take notes and categorize information, and provide a list of sources.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.9","grade":"4","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.9.a","grade":"4","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 4 Reading standards to literature (e.g., \"Describe in depth a character, setting, or event in a story or drama, drawing on specific details in the text [e.g., a character's thoughts, words, or actions].\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.9.b","grade":"4","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 4 Reading standards to informational texts (e.g., \"Explain how an author uses reasons and evidence to support particular points in a text\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"W.4.10","grade":"4","strand":"W","section":"Range of Writing:","description":"Write routinely over extended time frames (time for research, reflection, and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/4/","applicable":true},{"code":"SL.4.1","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Engage effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grade 4 topics and texts, building on others' ideas and expressing their own clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.1.a","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read or studied required material; explicitly draw on that preparation and other information known about the topic to explore ideas under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.1.b","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow agreed-upon rules for discussions and carry out assigned roles.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.1.c","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Pose and respond to specific questions to clarify or follow up on information, and make comments that contribute to the discussion and link to the remarks of others.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.1.d","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Review the key ideas expressed and explain their own ideas and understanding in light of the discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.2","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Paraphrase portions of a text read aloud or information presented in diverse media and formats, including visually, quantitatively, and orally.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.3","grade":"4","strand":"SL","section":"Comprehension and Collaboration:","description":"Identify the reasons and evidence a speaker provides to support particular points.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.4","grade":"4","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Report on a topic or text, tell a story, or recount an experience in an organized manner, using appropriate facts and relevant, descriptive details to support main ideas or themes; speak clearly at an understandable pace.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.5","grade":"4","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Add audio recordings and visual displays to presentations when appropriate to enhance the development of main ideas or themes.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"SL.4.6","grade":"4","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Differentiate between contexts that call for formal English (e.g., presenting ideas) and situations where informal discourse is appropriate (e.g., small-group discussion); use formal English when appropriate to task and situation. (See grade 4 Language standards 1 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/4/","applicable":true},{"code":"L.4.1","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.a","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Use relative pronouns (who, whose, whom, which, that) and relative adverbs (where, when, why).","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.b","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Form and use the progressive (e.g., I was walking; I am walking; I will be walking) verb tenses.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.c","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Use modal auxiliaries (e.g., can, may, must) to convey various conditions.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.d","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Order adjectives within sentences according to conventional patterns (e.g., a small red bag rather than a red small bag).","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.e","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Form and use prepositional phrases.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.f","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Produce complete sentences, recognizing and correcting inappropriate fragments and run-ons.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.1.g","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Correctly use frequently confused words (e.g., to, too, two; there, their).*","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.2","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.2.a","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Use correct capitalization.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.2.b","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Use commas and quotation marks to mark direct speech and quotations from a text.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.2.c","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Use a comma before a coordinating conjunction in a compound sentence.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.2.d","grade":"4","strand":"L","section":"Conventions of Standard English:","description":"Spell grade-appropriate words correctly, consulting references as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.3","grade":"4","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.3.a","grade":"4","strand":"L","section":"Knowledge of Language:","description":"Choose words and phrases to convey ideas precisely.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.3.b","grade":"4","strand":"L","section":"Knowledge of Language:","description":"Choose punctuation for effect.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.3.c","grade":"4","strand":"L","section":"Knowledge of Language:","description":"Differentiate between contexts that call for formal English (e.g., presenting ideas) and situations where informal discourse is appropriate (e.g., small-group discussion).","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.4","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grade 4 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.4.a","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., definitions, examples, or restatements in text) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.4.b","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use common, grade-appropriate Greek and Latin affixes and roots as clues to the meaning of a word (e.g., telegraph, photograph, autograph).","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.4.c","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation and determine or clarify the precise meaning of key words and phrases.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.5","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.5.a","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Explain the meaning of simple similes and metaphors (e.g., as pretty as a picture) in context.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.5.b","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Recognize and explain the meaning of common idioms, adages, and proverbs.","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.5.c","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of words by relating them to their opposites (antonyms) and to words with similar but not identical meanings (synonyms).","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"L.4.6","grade":"4","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately grade-appropriate general academic and domain-specific words and phrases, including those that signal precise actions, emotions, or states of being (e.g., quizzed, whined, stammered) and that are basic to a particular topic (e.g., wildlife, conservation, and endangered when discussing animal preservation).","source":"https://www.thecorestandards.org/ELA-Literacy/L/4/","applicable":true},{"code":"RF.4.3","grade":"4","strand":"RF","section":"Phonics and Word Recognition:","description":"Know and apply grade-level phonics and word analysis skills in decoding words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/4/","applicable":true},{"code":"RF.4.3.a","grade":"4","strand":"RF","section":"Phonics and Word Recognition:","description":"Use combined knowledge of all letter-sound correspondences, syllabication patterns, and morphology (e.g., roots and affixes) to read accurately unfamiliar multisyllabic words in context and out of context.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/4/","applicable":true},{"code":"RF.4.4","grade":"4","strand":"RF","section":"Fluency:","description":"Read with sufficient accuracy and fluency to support comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/4/","applicable":true},{"code":"RF.4.4.a","grade":"4","strand":"RF","section":"Fluency:","description":"Read grade-level text with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/4/","applicable":true},{"code":"RF.4.4.b","grade":"4","strand":"RF","section":"Fluency:","description":"Read grade-level prose and poetry orally with accuracy, appropriate rate, and expression on successive readings.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/4/","applicable":true},{"code":"RF.4.4.c","grade":"4","strand":"RF","section":"Fluency:","description":"Use context to confirm or self-correct word recognition and understanding, rereading as necessary.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/4/","applicable":true},{"code":"RL.5.1","grade":"5","strand":"RL","section":"Key Ideas and Details:","description":"Quote accurately from a text when explaining what the text says explicitly and when drawing inferences from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.2","grade":"5","strand":"RL","section":"Key Ideas and Details:","description":"Determine a theme of a story, drama, or poem from details in the text, including how characters in a story or drama respond to challenges or how the speaker in a poem reflects upon a topic; summarize the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.3","grade":"5","strand":"RL","section":"Key Ideas and Details:","description":"Compare and contrast two or more characters, settings, or events in a story or drama, drawing on specific details in the text (e.g., how characters interact).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.4","grade":"5","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative language such as metaphors and similes.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.5","grade":"5","strand":"RL","section":"Craft and Structure:","description":"Explain how a series of chapters, scenes, or stanzas fits together to provide the overall structure of a particular story, drama, or poem.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.6","grade":"5","strand":"RL","section":"Craft and Structure:","description":"Describe how a narrator's or speaker's point of view influences how events are described.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.7","grade":"5","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Analyze how visual and multimedia elements contribute to the meaning, tone, or beauty of a text (e.g., graphic novel, multimedia presentation of fiction, folktale, myth, poem).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.8","grade":"5","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.5.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":false},{"code":"RL.5.9","grade":"5","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast stories in the same genre (e.g., mysteries and adventure stories) on their approaches to similar themes and topics.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RL.5.10","grade":"5","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories, dramas, and poetry, at the high end of the grades 4-5 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/5/","applicable":true},{"code":"RI.5.1","grade":"5","strand":"RI","section":"Key Ideas and Details:","description":"Quote accurately from a text when explaining what the text says explicitly and when drawing inferences from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.2","grade":"5","strand":"RI","section":"Key Ideas and Details:","description":"Determine two or more main ideas of a text and explain how they are supported by key details; summarize the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.3","grade":"5","strand":"RI","section":"Key Ideas and Details:","description":"Explain the relationships or interactions between two or more individuals, events, ideas, or concepts in a historical, scientific, or technical text based on specific information in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.4","grade":"5","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of general academic and domain-specific words and phrases in a text relevant to a grade 5 topic or subject area.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.5","grade":"5","strand":"RI","section":"Craft and Structure:","description":"Compare and contrast the overall structure (e.g., chronology, comparison, cause/effect, problem/solution) of events, ideas, concepts, or information in two or more texts.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.6","grade":"5","strand":"RI","section":"Craft and Structure:","description":"Analyze multiple accounts of the same event or topic, noting important similarities and differences in the point of view they represent.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.7","grade":"5","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Draw on information from multiple print or digital sources, demonstrating the ability to locate an answer to a question quickly or to solve a problem efficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.8","grade":"5","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Explain how an author uses reasons and evidence to support particular points in a text, identifying which reasons and evidence support which point(s).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.9","grade":"5","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Integrate information from several texts on the same topic in order to write or speak about the subject knowledgeably.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"RI.5.10","grade":"5","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend informational texts, including history/social studies, science, and technical texts, at the high end of the grades 4-5 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/5/","applicable":true},{"code":"W.5.1","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Write opinion pieces on topics or texts, supporting a point of view with reasons and information.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.1.a","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic or text clearly, state an opinion, and create an organizational structure in which ideas are logically grouped to support the writer's purpose.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.1.b","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Provide logically ordered reasons that are supported by facts and details.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.1.c","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Link opinion and reasons using words, phrases, and clauses (e.g., consequently, specifically).","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.1.d","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section related to the opinion presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.2","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine a topic and convey ideas and information clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.2.a","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic clearly, provide a general observation and focus, and group related information logically; include formatting (e.g., headings), illustrations, and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.2.b","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with facts, definitions, concrete details, quotations, or other information and examples related to the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.2.c","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Link ideas within and across categories of information using words, phrases, and clauses (e.g., in contrast, especially).","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.2.d","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to inform about or explain the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.2.e","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section related to the information or explanation presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.3","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, descriptive details, and clear event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.3.a","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Orient the reader by establishing a situation and introducing a narrator and/or characters; organize an event sequence that unfolds naturally.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.3.b","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Use narrative techniques, such as dialogue, description, and pacing, to develop experiences and events or show the responses of characters to situations.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.3.c","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of transitional words, phrases, and clauses to manage the sequence of events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.3.d","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Use concrete words and phrases and sensory details to convey experiences and events precisely.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.3.e","grade":"5","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from the narrated experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.4","grade":"5","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development and organization are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.5","grade":"5","strand":"W","section":"Production and Distribution of Writing:","description":"With guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grade 5 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.6","grade":"5","strand":"W","section":"Production and Distribution of Writing:","description":"With some guidance and support from adults, use technology, including the Internet, to produce and publish writing as well as to interact and collaborate with others; demonstrate sufficient command of keyboarding skills to type a minimum of two pages in a single sitting.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.7","grade":"5","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects that use several sources to build knowledge through investigation of different aspects of a topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.8","grade":"5","strand":"W","section":"Research to Build and Present Knowledge:","description":"Recall relevant information from experiences or gather relevant information from print and digital sources; summarize or paraphrase information in notes and finished work, and provide a list of sources.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.9","grade":"5","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.9.a","grade":"5","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 5 Reading standards to literature (e.g., \"Compare and contrast two or more characters, settings, or events in a story or a drama, drawing on specific details in the text [e.g., how characters interact]\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.9.b","grade":"5","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 5 Reading standards to informational texts (e.g., \"Explain how an author uses reasons and evidence to support particular points in a text, identifying which reasons and evidence support which point[s]\"\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"W.5.10","grade":"5","strand":"W","section":"Range of Writing:","description":"Write routinely over extended time frames (time for research, reflection, and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/5/","applicable":true},{"code":"SL.5.1","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Engage effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grade 5 topics and texts, building on others' ideas and expressing their own clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.1.a","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read or studied required material; explicitly draw on that preparation and other information known about the topic to explore ideas under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.1.b","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow agreed-upon rules for discussions and carry out assigned roles.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.1.c","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Pose and respond to specific questions by making comments that contribute to the discussion and elaborate on the remarks of others.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.1.d","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Review the key ideas expressed and draw conclusions in light of information and knowledge gained from the discussions.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.2","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Summarize a written text read aloud or information presented in diverse media and formats, including visually, quantitatively, and orally.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.3","grade":"5","strand":"SL","section":"Comprehension and Collaboration:","description":"Summarize the points a speaker makes and explain how each claim is supported by reasons and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.4","grade":"5","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Report on a topic or text or present an opinion, sequencing ideas logically and using appropriate facts and relevant, descriptive details to support main ideas or themes; speak clearly at an understandable pace.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.5","grade":"5","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Include multimedia components (e.g., graphics, sound) and visual displays in presentations when appropriate to enhance the development of main ideas or themes.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"SL.5.6","grade":"5","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Adapt speech to a variety of contexts and tasks, using formal English when appropriate to task and situation. (See grade 5 Language standards 1 and 3 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/5/","applicable":true},{"code":"L.5.1","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.1.a","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Explain the function of conjunctions, prepositions, and interjections in general and their function in particular sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.1.b","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Form and use the perfect (e.g., I had walked; I have walked; I will have walked) verb tenses.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.1.c","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Use verb tense to convey various times, sequences, states, and conditions.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.1.d","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Recognize and correct inappropriate shifts in verb tense.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.1.e","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Use correlative conjunctions (e.g., either/or, neither/nor).","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.2","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.2.a","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Use punctuation to separate items in a series.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.2.b","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Use a comma to separate an introductory element from the rest of the sentence.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.2.c","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Use a comma to set off the words yes and no (e.g., Yes, thank you), to set off a tag question from the rest of the sentence (e.g., It's true, isn't it?), and to indicate direct address (e.g., Is that you, Steve?).","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.2.d","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Use underlining, quotation marks, or italics to indicate titles of works.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.2.e","grade":"5","strand":"L","section":"Conventions of Standard English:","description":"Spell grade-appropriate words correctly, consulting references as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.3","grade":"5","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.3.a","grade":"5","strand":"L","section":"Knowledge of Language:","description":"Expand, combine, and reduce sentences for meaning, reader/listener interest, and style.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.3.b","grade":"5","strand":"L","section":"Knowledge of Language:","description":"Compare and contrast the varieties of English (e.g., dialects, registers) used in stories, dramas, or poems.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.4","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grade 5 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.4.a","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., cause/effect relationships and comparisons in text) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.4.b","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use common, grade-appropriate Greek and Latin affixes and roots as clues to the meaning of a word (e.g., photograph, photosynthesis).","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.4.c","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation and determine or clarify the precise meaning of key words and phrases.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.5","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.5.a","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Interpret figurative language, including similes and metaphors, in context.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.5.b","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Recognize and explain the meaning of common idioms, adages, and proverbs.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.5.c","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use the relationship between particular words (e.g., synonyms, antonyms, homographs) to better understand each of the words.","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"L.5.6","grade":"5","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately grade-appropriate general academic and domain-specific words and phrases, including those that signal contrast, addition, and other logical relationships (e.g., however, although, nevertheless, similarly, moreover, in addition).","source":"https://www.thecorestandards.org/ELA-Literacy/L/5/","applicable":true},{"code":"RF.5.3","grade":"5","strand":"RF","section":"Phonics and Word Recognition:","description":"Know and apply grade-level phonics and word analysis skills in decoding words.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/5/","applicable":true},{"code":"RF.5.3.a","grade":"5","strand":"RF","section":"Phonics and Word Recognition:","description":"Use combined knowledge of all letter-sound correspondences, syllabication patterns, and morphology (e.g., roots and affixes) to read accurately unfamiliar multisyllabic words in context and out of context.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/5/","applicable":true},{"code":"RF.5.4","grade":"5","strand":"RF","section":"Fluency:","description":"Read with sufficient accuracy and fluency to support comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/5/","applicable":true},{"code":"RF.5.4.a","grade":"5","strand":"RF","section":"Fluency:","description":"Read grade-level text with purpose and understanding.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/5/","applicable":true},{"code":"RF.5.4.b","grade":"5","strand":"RF","section":"Fluency:","description":"Read grade-level prose and poetry orally with accuracy, appropriate rate, and expression on successive readings.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/5/","applicable":true},{"code":"RF.5.4.c","grade":"5","strand":"RF","section":"Fluency:","description":"Use context to confirm or self-correct word recognition and understanding, rereading as necessary.","source":"https://www.thecorestandards.org/ELA-Literacy/RF/5/","applicable":true},{"code":"RL.6.1","grade":"6","strand":"RL","section":"Key Ideas and Details:","description":"Cite textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.2","grade":"6","strand":"RL","section":"Key Ideas and Details:","description":"Determine a theme or central idea of a text and how it is conveyed through particular details; provide a summary of the text distinct from personal opinions or judgments.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.3","grade":"6","strand":"RL","section":"Key Ideas and Details:","description":"Describe how a particular story's or drama's plot unfolds in a series of episodes as well as how the characters respond or change as the plot moves toward a resolution.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.4","grade":"6","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative and connotative meanings; analyze the impact of a specific word choice on meaning and tone","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.5","grade":"6","strand":"RL","section":"Craft and Structure:","description":"Analyze how a particular sentence, chapter, scene, or stanza fits into the overall structure of a text and contributes to the development of the theme, setting, or plot.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.6","grade":"6","strand":"RL","section":"Craft and Structure:","description":"Explain how an author develops the point of view of the narrator or speaker in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.7","grade":"6","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the experience of reading a story, drama, or poem to listening to or viewing an audio, video, or live version of the text, including contrasting what they \"see\" and \"hear\" when reading the text to what they perceive when they listen or watch.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.8","grade":"6","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.6.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":false},{"code":"RL.6.9","grade":"6","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast texts in different forms or genres (e.g., stories and poems; historical novels and fantasy stories) in terms of their approaches to similar themes and topics.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RL.6.10","grade":"6","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories, dramas, and poems, in the grades 6-8 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/6/","applicable":true},{"code":"RI.6.1","grade":"6","strand":"RI","section":"Key Ideas and Details:","description":"Cite textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.2","grade":"6","strand":"RI","section":"Key Ideas and Details:","description":"Determine a central idea of a text and how it is conveyed through particular details; provide a summary of the text distinct from personal opinions or judgments.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.3","grade":"6","strand":"RI","section":"Key Ideas and Details:","description":"Analyze in detail how a key individual, event, or idea is introduced, illustrated, and elaborated in a text (e.g., through examples or anecdotes).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.4","grade":"6","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative, connotative, and technical meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.5","grade":"6","strand":"RI","section":"Craft and Structure:","description":"Analyze how a particular sentence, paragraph, chapter, or section fits into the overall structure of a text and contributes to the development of the ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.6","grade":"6","strand":"RI","section":"Craft and Structure:","description":"Determine an author's point of view or purpose in a text and explain how it is conveyed in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.7","grade":"6","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Integrate information presented in different media or formats (e.g., visually, quantitatively) as well as in words to develop a coherent understanding of a topic or issue.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.8","grade":"6","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Trace and evaluate the argument and specific claims in a text, distinguishing claims that are supported by reasons and evidence from claims that are not.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.9","grade":"6","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast one author's presentation of events with that of another (e.g., a memoir written by and a biography on the same person).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"RI.6.10","grade":"6","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literary nonfiction in the grades 6-8 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/6/","applicable":true},{"code":"W.6.1","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Write arguments to support claims with clear reasons and relevant evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.1.a","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Introduce claim(s) and organize the reasons and evidence clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.1.b","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Support claim(s) with clear reasons and relevant evidence, using credible sources and demonstrating an understanding of the topic or text.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.1.c","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses to clarify the relationships among claim(s) and reasons.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.1.d","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.1.e","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine a topic and convey ideas, concepts, and information through the selection, organization, and analysis of relevant content.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2.a","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic; organize ideas, concepts, and information, using strategies such as definition, classification, comparison/contrast, and cause/effect; include formatting (e.g., headings), graphics (e.g., charts, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2.b","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with relevant facts, definitions, concrete details, quotations, or other information and examples.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2.c","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Use appropriate transitions to clarify the relationships among ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2.d","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to inform about or explain the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2.e","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.2.f","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from the information or explanation presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.3","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, relevant descriptive details, and well-structured event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.3.a","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Engage and orient the reader by establishing a context and introducing a narrator and/or characters; organize an event sequence that unfolds naturally and logically.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.3.b","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Use narrative techniques, such as dialogue, pacing, and description, to develop experiences, events, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.3.c","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of transition words, phrases, and clauses to convey sequence and signal shifts from one time frame or setting to another.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.3.d","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Use precise words and phrases, relevant descriptive details, and sensory language to convey experiences and events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.3.e","grade":"6","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from the narrated experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.4","grade":"6","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.5","grade":"6","strand":"W","section":"Production and Distribution of Writing:","description":"With some guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grade 6 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.6","grade":"6","strand":"W","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce and publish writing as well as to interact and collaborate with others; demonstrate sufficient command of keyboarding skills to type a minimum of three pages in a single sitting.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.7","grade":"6","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects to answer a question, drawing on several sources and refocusing the inquiry when appropriate.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.8","grade":"6","strand":"W","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple print and digital sources; assess the credibility of each source; and quote or paraphrase the data and conclusions of others while avoiding plagiarism and providing basic bibliographic information for sources.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.9","grade":"6","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.9.a","grade":"6","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 6 Reading standards to literature (e.g., \"Compare and contrast texts in different forms or genres [e.g., stories and poems; historical novels and fantasy stories] in terms of their approaches to similar themes and topics\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.9.b","grade":"6","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 6 Reading standards to literary nonfiction (e.g., \"Trace and evaluate the argument and specific claims in a text, distinguishing claims that are supported by reasons and evidence from claims that are not\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"W.6.10","grade":"6","strand":"W","section":"Range of Writing:","description":"Write routinely over extended time frames (time for research, reflection, and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/6/","applicable":true},{"code":"SL.6.1","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Engage effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grade 6 topics, texts, and issues, building on others' ideas and expressing their own clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.1.a","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read or studied required material; explicitly draw on that preparation by referring to evidence on the topic, text, or issue to probe and reflect on ideas under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.1.b","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow rules for collegial discussions, set specific goals and deadlines, and define individual roles as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.1.c","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Pose and respond to specific questions with elaboration and detail by making comments that contribute to the topic, text, or issue under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.1.d","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Review the key ideas expressed and demonstrate understanding of multiple perspectives through reflection and paraphrasing.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.2","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Interpret information presented in diverse media and formats (e.g., visually, quantitatively, orally) and explain how it contributes to a topic, text, or issue under study.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.3","grade":"6","strand":"SL","section":"Comprehension and Collaboration:","description":"Delineate a speaker's argument and specific claims, distinguishing claims that are supported by reasons and evidence from claims that are not.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.4","grade":"6","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Present claims and findings, sequencing ideas logically and using pertinent descriptions, facts, and details to accentuate main ideas or themes; use appropriate eye contact, adequate volume, and clear pronunciation.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.5","grade":"6","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Include multimedia components (e.g., graphics, images, music, sound) and visual displays in presentations to clarify information.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"SL.6.6","grade":"6","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Adapt speech to a variety of contexts and tasks, demonstrating command of formal English when indicated or appropriate. (See grade 6 Language standards 1 and 3 for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/6/","applicable":true},{"code":"L.6.1","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.1.a","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Ensure that pronouns are in the proper case (subjective, objective, possessive).","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.1.b","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Use intensive pronouns (e.g., myself, ourselves).","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.1.c","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Recognize and correct inappropriate shifts in pronoun number and person.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.1.d","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Recognize and correct vague pronouns (i.e., ones with unclear or ambiguous antecedents).*","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.1.e","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Recognize variations from standard English in their own and others' writing and speaking, and identify and use strategies to improve expression in conventional language.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.2","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.2.a","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Use punctuation (commas, parentheses, dashes) to set off nonrestrictive/parenthetical elements.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.2.b","grade":"6","strand":"L","section":"Conventions of Standard English:","description":"Spell correctly.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.3","grade":"6","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.3.a","grade":"6","strand":"L","section":"Knowledge of Language:","description":"Vary sentence patterns for meaning, reader/listener interest, and style.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.3.b","grade":"6","strand":"L","section":"Knowledge of Language:","description":"Maintain consistency in style and tone.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.4","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grade 6 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.4.a","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., the overall meaning of a sentence or paragraph; a word's position or function in a sentence) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.4.b","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use common, grade-appropriate Greek or Latin affixes and roots as clues to the meaning of a word (e.g., audience, auditory, audible).","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.4.c","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation of a word or determine or clarify its precise meaning or its part of speech.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.4.d","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Verify the preliminary determination of the meaning of a word or phrase (e.g., by checking the inferred meaning in context or in a dictionary).","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.5","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.5.a","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Interpret figures of speech (e.g., personification) in context.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.5.b","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use the relationship between particular words (e.g., cause/effect, part/whole, item/category) to better understand each of the words.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.5.c","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish among the connotations (associations) of words with similar denotations (definitions) (e.g., stingy, scrimping, economical, unwasteful, thrifty).","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"L.6.6","grade":"6","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately grade-appropriate general academic and domain-specific words and phrases; gather vocabulary knowledge when considering a word or phrase important to comprehension or expression.","source":"https://www.thecorestandards.org/ELA-Literacy/L/6/","applicable":true},{"code":"RL.7.1","grade":"7","strand":"RL","section":"Key Ideas and Details:","description":"Cite several pieces of textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.2","grade":"7","strand":"RL","section":"Key Ideas and Details:","description":"Determine a theme or central idea of a text and analyze its development over the course of the text; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.3","grade":"7","strand":"RL","section":"Key Ideas and Details:","description":"Analyze how particular elements of a story or drama interact (e.g., how setting shapes the characters or plot).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.4","grade":"7","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative and connotative meanings; analyze the impact of rhymes and other repetitions of sounds (e.g., alliteration) on a specific verse or stanza of a poem or section of a story or drama.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.5","grade":"7","strand":"RL","section":"Craft and Structure:","description":"Analyze how a drama's or poem's form or structure (e.g., soliloquy, sonnet) contributes to its meaning","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.6","grade":"7","strand":"RL","section":"Craft and Structure:","description":"Analyze how an author develops and contrasts the points of view of different characters or narrators in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.7","grade":"7","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast a written story, drama, or poem to its audio, filmed, staged, or multimedia version, analyzing the effects of techniques unique to each medium (e.g., lighting, sound, color, or camera focus and angles in a film).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.8","grade":"7","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.7.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":false},{"code":"RL.7.9","grade":"7","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast a fictional portrayal of a time, place, or character and a historical account of the same period as a means of understanding how authors of fiction use or alter history.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RL.7.10","grade":"7","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories, dramas, and poems, in the grades 6-8 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/7/","applicable":true},{"code":"RI.7.1","grade":"7","strand":"RI","section":"Key Ideas and Details:","description":"Cite several pieces of textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.2","grade":"7","strand":"RI","section":"Key Ideas and Details:","description":"Determine two or more central ideas in a text and analyze their development over the course of the text; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.3","grade":"7","strand":"RI","section":"Key Ideas and Details:","description":"Analyze the interactions between individuals, events, and ideas in a text (e.g., how ideas influence individuals or events, or how individuals influence ideas or events).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.4","grade":"7","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative, connotative, and technical meanings; analyze the impact of a specific word choice on meaning and tone.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.5","grade":"7","strand":"RI","section":"Craft and Structure:","description":"Analyze the structure an author uses to organize a text, including how the major sections contribute to the whole and to the development of the ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.6","grade":"7","strand":"RI","section":"Craft and Structure:","description":"Determine an author's point of view or purpose in a text and analyze how the author distinguishes his or her position from that of others.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.7","grade":"7","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast a text to an audio, video, or multimedia version of the text, analyzing each medium's portrayal of the subject (e.g., how the delivery of a speech affects the impact of the words).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.8","grade":"7","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Trace and evaluate the argument and specific claims in a text, assessing whether the reasoning is sound and the evidence is relevant and sufficient to support the claims.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.9","grade":"7","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Analyze how two or more authors writing about the same topic shape their presentations of key information by emphasizing different evidence or advancing different interpretations of facts.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"RI.7.10","grade":"7","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literary nonfiction in the grades 6-8 text complexity band proficiently, with scaffolding as needed at the high end of the range.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/7/","applicable":true},{"code":"W.7.1","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Write arguments to support claims with clear reasons and relevant evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.1.a","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Introduce claim(s), acknowledge alternate or opposing claims, and organize the reasons and evidence logically.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.1.b","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Support claim(s) with logical reasoning and relevant evidence, using accurate, credible sources and demonstrating an understanding of the topic or text.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.1.c","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses to create cohesion and clarify the relationships among claim(s), reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.1.d","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.1.e","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine a topic and convey ideas, concepts, and information through the selection, organization, and analysis of relevant content.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2.a","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic clearly, previewing what is to follow; organize ideas, concepts, and information, using strategies such as definition, classification, comparison/contrast, and cause/effect; include formatting (e.g., headings), graphics (e.g., charts, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2.b","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with relevant facts, definitions, concrete details, quotations, or other information and examples.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2.c","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Use appropriate transitions to create cohesion and clarify the relationships among ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2.d","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to inform about or explain the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2.e","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.2.f","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.3","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, relevant descriptive details, and well-structured event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.3.a","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Engage and orient the reader by establishing a context and point of view and introducing a narrator and/or characters; organize an event sequence that unfolds naturally and logically.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.3.b","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Use narrative techniques, such as dialogue, pacing, and description, to develop experiences, events, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.3.c","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of transition words, phrases, and clauses to convey sequence and signal shifts from one time frame or setting to another.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.3.d","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Use precise words and phrases, relevant descriptive details, and sensory language to capture the action and convey experiences and events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.3.e","grade":"7","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from and reflects on the narrated experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.4","grade":"7","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.5","grade":"7","strand":"W","section":"Production and Distribution of Writing:","description":"With some guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on how well purpose and audience have been addressed. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grade 7 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.6","grade":"7","strand":"W","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce and publish writing and link to and cite sources as well as to interact and collaborate with others, including linking to and citing sources.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.7","grade":"7","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects to answer a question, drawing on several sources and generating additional related, focused questions for further research and investigation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.8","grade":"7","strand":"W","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple print and digital sources, using search terms effectively; assess the credibility and accuracy of each source; and quote or paraphrase the data and conclusions of others while avoiding plagiarism and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.9","grade":"7","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.9.a","grade":"7","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 7 Reading standards to literature (e.g., \"Compare and contrast a fictional portrayal of a time, place, or character and a historical account of the same period as a means of understanding how authors of fiction use or alter history\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.9.b","grade":"7","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 7 Reading standards to literary nonfiction (e.g. \"Trace and evaluate the argument and specific claims in a text, assessing whether the reasoning is sound and the evidence is relevant and sufficient to support the claims\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"W.7.10","grade":"7","strand":"W","section":"Range of Writing:","description":"Write routinely over extended time frames (time for research, reflection, and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/7/","applicable":true},{"code":"SL.7.1","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Engage effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grade 7 topics, texts, and issues, building on others' ideas and expressing their own clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.1.a","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read or researched material under study; explicitly draw on that preparation by referring to evidence on the topic, text, or issue to probe and reflect on ideas under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.1.b","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow rules for collegial discussions, track progress toward specific goals and deadlines, and define individual roles as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.1.c","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Pose questions that elicit elaboration and respond to others' questions and comments with relevant observations and ideas that bring the discussion back on topic as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.1.d","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Acknowledge new information expressed by others and, when warranted, modify their own views.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.2","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Analyze the main ideas and supporting details presented in diverse media and formats (e.g., visually, quantitatively, orally) and explain how the ideas clarify a topic, text, or issue under study.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.3","grade":"7","strand":"SL","section":"Comprehension and Collaboration:","description":"Delineate a speaker's argument and specific claims, evaluating the soundness of the reasoning and the relevance and sufficiency of the evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.4","grade":"7","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Present claims and findings, emphasizing salient points in a focused, coherent manner with pertinent descriptions, facts, details, and examples; use appropriate eye contact, adequate volume, and clear pronunciation.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.5","grade":"7","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Include multimedia components and visual displays in presentations to clarify claims and findings and emphasize salient points.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"SL.7.6","grade":"7","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Adapt speech to a variety of contexts and tasks, demonstrating command of formal English when indicated or appropriate. (See grade 7 Language standards 1 and 3 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/7/","applicable":true},{"code":"L.7.1","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.1.a","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Explain the function of phrases and clauses in general and their function in specific sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.1.b","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Choose among simple, compound, complex, and compound-complex sentences to signal differing relationships among ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.1.c","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Place phrases and clauses within a sentence, recognizing and correcting misplaced and dangling modifiers.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.2","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.2.a","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Use a comma to separate coordinate adjectives (e.g., It was a fascinating, enjoyable movie but not He wore an old[,] green shirt).","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.2.b","grade":"7","strand":"L","section":"Conventions of Standard English:","description":"Spell correctly.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.3","grade":"7","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.3.a","grade":"7","strand":"L","section":"Knowledge of Language:","description":"Choose language that expresses ideas precisely and concisely, recognizing and eliminating wordiness and redundancy.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.4","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grade 7 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.4.a","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., the overall meaning of a sentence or paragraph; a word's position or function in a sentence) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.4.b","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use common, grade-appropriate Greek or Latin affixes and roots as clues to the meaning of a word (e.g., belligerent, bellicose, rebel).","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.4.c","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult general and specialized reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation of a word or determine or clarify its precise meaning or its part of speech.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.4.d","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Verify the preliminary determination of the meaning of a word or phrase (e.g., by checking the inferred meaning in context or in a dictionary).","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.5","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.5.a","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Interpret figures of speech (e.g., literary, biblical, and mythological allusions) in context.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.5.b","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use the relationship between particular words (e.g., synonym/antonym, analogy) to better understand each of the words.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.5.c","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish among the connotations (associations) of words with similar denotations (definitions) (e.g., refined, respectful, polite, diplomatic, condescending).","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"L.7.6","grade":"7","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately grade-appropriate general academic and domain-specific words and phrases; gather vocabulary knowledge when considering a word or phrase important to comprehension or expression.","source":"https://www.thecorestandards.org/ELA-Literacy/L/7/","applicable":true},{"code":"RL.8.1","grade":"8","strand":"RL","section":"Key Ideas and Details:","description":"Cite the textual evidence that most strongly supports an analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.2","grade":"8","strand":"RL","section":"Key Ideas and Details:","description":"Determine a theme or central idea of a text and analyze its development over the course of the text, including its relationship to the characters, setting, and plot; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.3","grade":"8","strand":"RL","section":"Key Ideas and Details:","description":"Analyze how particular lines of dialogue or incidents in a story or drama propel the action, reveal aspects of a character, or provoke a decision.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.4","grade":"8","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative and connotative meanings; analyze the impact of specific word choices on meaning and tone, including analogies or allusions to other texts.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.5","grade":"8","strand":"RL","section":"Craft and Structure:","description":"Compare and contrast the structure of two or more texts and analyze how the differing structure of each text contributes to its meaning and style.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.6","grade":"8","strand":"RL","section":"Craft and Structure:","description":"Analyze how differences in the points of view of the characters and the audience or reader (e.g., created through the use of dramatic irony) create such effects as suspense or humor.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.7","grade":"8","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Analyze the extent to which a filmed or live production of a story or drama stays faithful to or departs from the text or script, evaluating the choices made by the director or actors.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.8","grade":"8","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.8.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":false},{"code":"RL.8.9","grade":"8","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Analyze how a modern work of fiction draws on themes, patterns of events, or character types from myths, traditional stories, or religious works such as the Bible, including describing how the material is rendered new.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RL.8.10","grade":"8","strand":"RL","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literature, including stories, dramas, and poems, at the high end of grades 6-8 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/8/","applicable":true},{"code":"RI.8.1","grade":"8","strand":"RI","section":"Key Ideas and Details:","description":"Cite the textual evidence that most strongly supports an analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.2","grade":"8","strand":"RI","section":"Key Ideas and Details:","description":"Determine a central idea of a text and analyze its development over the course of the text, including its relationship to supporting ideas; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.3","grade":"8","strand":"RI","section":"Key Ideas and Details:","description":"Analyze how a text makes connections among and distinctions between individuals, ideas, or events (e.g., through comparisons, analogies, or categories).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.4","grade":"8","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative, connotative, and technical meanings; analyze the impact of specific word choices on meaning and tone, including analogies or allusions to other texts.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.5","grade":"8","strand":"RI","section":"Craft and Structure:","description":"Analyze in detail the structure of a specific paragraph in a text, including the role of particular sentences in developing and refining a key concept.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.6","grade":"8","strand":"RI","section":"Craft and Structure:","description":"Determine an author's point of view or purpose in a text and analyze how the author acknowledges and responds to conflicting evidence or viewpoints.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.7","grade":"8","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Evaluate the advantages and disadvantages of using different mediums (e.g., print or digital text, video, multimedia) to present a particular topic or idea.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.8","grade":"8","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Delineate and evaluate the argument and specific claims in a text, assessing whether the reasoning is sound and the evidence is relevant and sufficient; recognize when irrelevant evidence is introduced.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.9","grade":"8","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Analyze a case in which two or more texts provide conflicting information on the same topic and identify where the texts disagree on matters of fact or interpretation.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"RI.8.10","grade":"8","strand":"RI","section":"Range of Reading and Level of Text Complexity:","description":"By the end of the year, read and comprehend literary nonfiction at the high end of the grades 6-8 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/8/","applicable":true},{"code":"W.8.1","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Write arguments to support claims with clear reasons and relevant evidence","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.1.a","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Introduce claim(s), acknowledge and distinguish the claim(s) from alternate or opposing claims, and organize the reasons and evidence logically.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.1.b","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Support claim(s) with logical reasoning and relevant evidence, using accurate, credible sources and demonstrating an understanding of the topic or text.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.1.c","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses to create cohesion and clarify the relationships among claim(s), counterclaims, reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.1.d","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.1.e","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine a topic and convey ideas, concepts, and information through the selection, organization, and analysis of relevant content.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2.a","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic clearly, previewing what is to follow; organize ideas, concepts, and information into broader categories; include formatting (e.g., headings), graphics (e.g., charts, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2.b","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with relevant, well-chosen facts, definitions, concrete details, quotations, or other information and examples.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2.c","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Use appropriate and varied transitions to create cohesion and clarify the relationships among ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2.d","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to inform about or explain the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2.e","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.2.f","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.3","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, relevant descriptive details, and well-structured event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.3.a","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Engage and orient the reader by establishing a context and point of view and introducing a narrator and/or characters; organize an event sequence that unfolds naturally and logically.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.3.b","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Use narrative techniques, such as dialogue, pacing, description, and reflection, to develop experiences, events, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.3.c","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of transition words, phrases, and clauses to convey sequence, signal shifts from one time frame or setting to another, and show the relationships among experiences and events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.3.d","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Use precise words and phrases, relevant descriptive details, and sensory language to capture the action and convey experiences and events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.3.e","grade":"8","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from and reflects on the narrated experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.4","grade":"8","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.5","grade":"8","strand":"W","section":"Production and Distribution of Writing:","description":"With some guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on how well purpose and audience have been addressed. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grade 8 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.6","grade":"8","strand":"W","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce and publish writing and present the relationships between information and ideas efficiently as well as to interact and collaborate with others.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.7","grade":"8","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects to answer a question (including a self-generated question), drawing on several sources and generating additional related, focused questions that allow for multiple avenues of exploration.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.8","grade":"8","strand":"W","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple print and digital sources, using search terms effectively; assess the credibility and accuracy of each source; and quote or paraphrase the data and conclusions of others while avoiding plagiarism and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.9","grade":"8","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.9.a","grade":"8","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 8 Reading standards to literature (e.g., \"Analyze how a modern work of fiction draws on themes, patterns of events, or character types from myths, traditional stories, or religious works such as the Bible, including describing how the material is rendered new\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.9.b","grade":"8","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grade 8 Reading standards to literary nonfiction (e.g., \"Delineate and evaluate the argument and specific claims in a text, assessing whether the reasoning is sound and the evidence is relevant and sufficient; recognize when irrelevant evidence is introduced\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"W.8.10","grade":"8","strand":"W","section":"Range of Writing:","description":"Write routinely over extended time frames (time for research, reflection, and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/8/","applicable":true},{"code":"SL.8.1","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Engage effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grade 8 topics, texts, and issues, building on others' ideas and expressing their own clearly.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.1.a","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read or researched material under study; explicitly draw on that preparation by referring to evidence on the topic, text, or issue to probe and reflect on ideas under discussion.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.1.b","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Follow rules for collegial discussions and decision-making, track progress toward specific goals and deadlines, and define individual roles as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.1.c","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Pose questions that connect the ideas of several speakers and respond to others' questions and comments with relevant evidence, observations, and ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.1.d","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Acknowledge new information expressed by others, and, when warranted, qualify or justify their own views in light of the evidence presented.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.2","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Analyze the purpose of information presented in diverse media and formats (e.g., visually, quantitatively, orally) and evaluate the motives (e.g., social, commercial, political) behind its presentation.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.3","grade":"8","strand":"SL","section":"Comprehension and Collaboration:","description":"Delineate a speaker's argument and specific claims, evaluating the soundness of the reasoning and relevance and sufficiency of the evidence and identifying when irrelevant evidence is introduced.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.4","grade":"8","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Present claims and findings, emphasizing salient points in a focused, coherent manner with relevant evidence, sound valid reasoning, and well-chosen details; use appropriate eye contact, adequate volume, and clear pronunciation.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.5","grade":"8","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Integrate multimedia and visual displays into presentations to clarify information, strengthen claims and evidence, and add interest.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"SL.8.6","grade":"8","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Adapt speech to a variety of contexts and tasks, demonstrating command of formal English when indicated or appropriate. (See grade 8 Language standards 1 and 3 here for specific expectations.)","source":"https://www.thecorestandards.org/ELA-Literacy/SL/8/","applicable":true},{"code":"L.8.1","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.1.a","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Explain the function of verbals (gerunds, participles, infinitives) in general and their function in particular sentences.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.1.b","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Form and use verbs in the active and passive voice.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.1.c","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Form and use verbs in the indicative, imperative, interrogative, conditional, and subjunctive mood.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.1.d","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Recognize and correct inappropriate shifts in verb voice and mood.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.2","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.2.a","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Use punctuation (comma, ellipsis, dash) to indicate a pause or break.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.2.b","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Use an ellipsis to indicate an omission.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.2.c","grade":"8","strand":"L","section":"Conventions of Standard English:","description":"Spell correctly.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.3","grade":"8","strand":"L","section":"Knowledge of Language:","description":"Use knowledge of language and its conventions when writing, speaking, reading, or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.3.a","grade":"8","strand":"L","section":"Knowledge of Language:","description":"Use verbs in the active and passive voice and in the conditional and subjunctive mood to achieve particular effects (e.g., emphasizing the actor or the action; expressing uncertainty or describing a state contrary to fact).","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.4","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words or phrases based on grade 8 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.4.a","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., the overall meaning of a sentence or paragraph; a word's position or function in a sentence) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.4.b","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use common, grade-appropriate Greek or Latin affixes and roots as clues to the meaning of a word (e.g., precede, recede, secede).","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.4.c","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult general and specialized reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation of a word or determine or clarify its precise meaning or its part of speech.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.4.d","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Verify the preliminary determination of the meaning of a word or phrase (e.g., by checking the inferred meaning in context or in a dictionary).","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.5","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.5.a","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Interpret figures of speech (e.g. verbal irony, puns) in context.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.5.b","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use the relationship between particular words to better understand each of the words.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.5.c","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Distinguish among the connotations (associations) of words with similar denotations (definitions) (e.g., bullheaded, willful, firm, persistent, resolute).","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"L.8.6","grade":"8","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately grade-appropriate general academic and domain-specific words and phrases; gather vocabulary knowledge when considering a word or phrase important to comprehension or expression.","source":"https://www.thecorestandards.org/ELA-Literacy/L/8/","applicable":true},{"code":"RL.9-10.10","grade":"9-10","strand":"RL","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.1","grade":"9-10","strand":"RL","section":"Key Ideas and Details:","description":"Cite strong and thorough textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.2","grade":"9-10","strand":"RL","section":"Key Ideas and Details:","description":"Determine a theme or central idea of a text and analyze in detail its development over the course of the text, including how it emerges and is shaped and refined by specific details; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.3","grade":"9-10","strand":"RL","section":"Key Ideas and Details:","description":"Analyze how complex characters (e.g., those with multiple or conflicting motivations) develop over the course of a text, interact with other characters, and advance the plot or develop the theme.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.4","grade":"9-10","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in the text, including figurative and connotative meanings; analyze the cumulative impact of specific word choices on meaning and tone (e.g., how the language evokes a sense of time and place; how it sets a formal or informal tone).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.5","grade":"9-10","strand":"RL","section":"Craft and Structure:","description":"Analyze how an author's choices concerning how to structure a text, order events within it (e.g., parallel plots), and manipulate time (e.g., pacing, flashbacks) create such effects as mystery, tension, or surprise.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.6","grade":"9-10","strand":"RL","section":"Craft and Structure:","description":"Analyze a particular point of view or cultural experience reflected in a work of literature from outside the United States, drawing on a wide reading of world literature.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.7","grade":"9-10","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Analyze the representation of a subject or a key scene in two different artistic mediums, including what is emphasized or absent in each treatment (e.g., Auden's \"Musée des Beaux Arts\" and Breughel's Landscape with the Fall of Icarus).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RL.9-10.8","grade":"9-10","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.9-10.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":false},{"code":"RL.9-10.9","grade":"9-10","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Analyze how an author draws on and transforms source material in a specific work (e.g., how Shakespeare treats a theme or topic from Ovid or the Bible or how a later author draws on a play by Shakespeare).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/9-10/","applicable":true},{"code":"RI.9-10.10","grade":"9-10","strand":"RI","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.1","grade":"9-10","strand":"RI","section":"Key Ideas and Details:","description":"Cite strong and thorough textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.2","grade":"9-10","strand":"RI","section":"Key Ideas and Details:","description":"Determine a central idea of a text and analyze its development over the course of the text, including how it emerges and is shaped and refined by specific details; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.3","grade":"9-10","strand":"RI","section":"Key Ideas and Details:","description":"Analyze how the author unfolds an analysis or series of ideas or events, including the order in which the points are made, how they are introduced and developed, and the connections that are drawn between them.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.4","grade":"9-10","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative, connotative, and technical meanings; analyze the cumulative impact of specific word choices on meaning and tone (e.g., how the language of a court opinion differs from that of a newspaper).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.5","grade":"9-10","strand":"RI","section":"Craft and Structure:","description":"Analyze in detail how an author's ideas or claims are developed and refined by particular sentences, paragraphs, or larger portions of a text (e.g., a section or chapter).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.6","grade":"9-10","strand":"RI","section":"Craft and Structure:","description":"Determine an author's point of view or purpose in a text and analyze how an author uses rhetoric to advance that point of view or purpose.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.7","grade":"9-10","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Analyze various accounts of a subject told in different mediums (e.g., a person's life story in both print and multimedia), determining which details are emphasized in each account.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.8","grade":"9-10","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Delineate and evaluate the argument and specific claims in a text, assessing whether the reasoning is valid and the evidence is relevant and sufficient; identify false statements and fallacious reasoning.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"RI.9-10.9","grade":"9-10","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Analyze seminal U.S. documents of historical and literary significance (e.g., Washington's Farewell Address, the Gettysburg Address, Roosevelt's Four Freedoms speech, King's \"Letter from Birmingham Jail\"), including how they address related themes and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/9-10/","applicable":true},{"code":"W.9-10.10","grade":"9-10","strand":"W","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.1","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Write arguments to support claims in an analysis of substantive topics or texts, using valid reasoning and relevant and sufficient evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.1.a","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Introduce precise claim(s), distinguish the claim(s) from alternate or opposing claims, and create an organization that establishes clear relationships among claim(s), counterclaims, reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.1.b","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Develop claim(s) and counterclaims fairly, supplying evidence for each while pointing out the strengths and limitations of both in a manner that anticipates the audience's knowledge level and concerns.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.1.c","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses to link the major sections of the text, create cohesion, and clarify the relationships between claim(s) and reasons, between reasons and evidence, and between claim(s) and counterclaims.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.1.d","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.1.e","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine and convey complex ideas, concepts, and information clearly and accurately through the effective selection, organization, and analysis of content.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2.a","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic; organize complex ideas, concepts, and information to make important connections and distinctions; include formatting (e.g., headings), graphics (e.g., figures, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2.b","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic with well-chosen, relevant, and sufficient facts, extended definitions, concrete details, quotations, or other information and examples appropriate to the audience's knowledge of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2.c","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Use appropriate and varied transitions to link the major sections of the text, create cohesion, and clarify the relationships among complex ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2.d","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to manage the complexity of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2.e","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.2.f","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation presented (e.g., articulating implications or the significance of the topic).","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.3","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, well-chosen details, and well-structured event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.3.a","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Engage and orient the reader by setting out a problem, situation, or observation, establishing one or multiple point(s) of view, and introducing a narrator and/or characters; create a smooth progression of experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.3.b","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Use narrative techniques, such as dialogue, pacing, description, reflection, and multiple plot lines, to develop experiences, events, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.3.c","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of techniques to sequence events so that they build on one another to create a coherent whole.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.3.d","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Use precise words and phrases, telling details, and sensory language to convey a vivid picture of the experiences, events, setting, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.3.e","grade":"9-10","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from and reflects on what is experienced, observed, or resolved over the course of the narrative.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.4","grade":"9-10","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.5","grade":"9-10","strand":"W","section":"Production and Distribution of Writing:","description":"Develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on addressing what is most significant for a specific purpose and audience. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grades 9-10 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.6","grade":"9-10","strand":"W","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce, publish, and update individual or shared writing products, taking advantage of technology's capacity to link to other information and to display information flexibly and dynamically.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.7","grade":"9-10","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short as well as more sustained research projects to answer a question (including a self-generated question) or solve a problem; narrow or broaden the inquiry when appropriate; synthesize multiple sources on the subject, demonstrating understanding of the subject under investigation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.8","grade":"9-10","strand":"W","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple authoritative print and digital sources, using advanced searches effectively; assess the usefulness of each source in answering the research question; integrate information into the text selectively to maintain the flow of ideas, avoiding plagiarism and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.9","grade":"9-10","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.9.a","grade":"9-10","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grades 9-10 Reading standards to literature (e.g., \"Analyze how an author draws on and transforms source material in a specific work [e.g., how Shakespeare treats a theme or topic from Ovid or the Bible or how a later author draws on a play by Shakespeare]\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"W.9-10.9.b","grade":"9-10","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grades 9-10 Reading standards to literary nonfiction (e.g., \"Delineate and evaluate the argument and specific claims in a text, assessing whether the reasoning is valid and the evidence is relevant and sufficient; identify false statements and fallacious reasoning\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/9-10/","applicable":true},{"code":"SL.9-10.6","grade":"9-10","strand":"SL","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.1","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Initiate and participate effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grades 9-10 topics, texts, and issues, building on others' ideas and expressing their own clearly and persuasively.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.1.a","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read and researched material under study; explicitly draw on that preparation by referring to evidence from texts and other research on the topic or issue to stimulate a thoughtful, well-reasoned exchange of ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.1.b","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Work with peers to set rules for collegial discussions and decision-making (e.g., informal consensus, taking votes on key issues, presentation of alternate views), clear goals and deadlines, and individual roles as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.1.c","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Propel conversations by posing and responding to questions that relate the current discussion to broader themes or larger ideas; actively incorporate others into the discussion; and clarify, verify, or challenge ideas and conclusions.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.1.d","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Respond thoughtfully to diverse perspectives, summarize points of agreement and disagreement, and, when warranted, qualify or justify their own views and understanding and make new connections in light of the evidence and reasoning presented.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.2","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Integrate multiple sources of information presented in diverse media or formats (e.g., visually, quantitatively, orally) evaluating the credibility and accuracy of each source.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.3","grade":"9-10","strand":"SL","section":"Comprehension and Collaboration:","description":"Evaluate a speaker's point of view, reasoning, and use of evidence and rhetoric, identifying any fallacious reasoning or exaggerated or distorted evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.4","grade":"9-10","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Present information, findings, and supporting evidence clearly, concisely, and logically such that listeners can follow the line of reasoning and the organization, development, substance, and style are appropriate to purpose, audience, and task.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"SL.9-10.5","grade":"9-10","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Make strategic use of digital media (e.g., textual, graphical, audio, visual, and interactive elements) in presentations to enhance understanding of findings, reasoning, and evidence and to add interest.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/9-10/","applicable":true},{"code":"L.9-10.1","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.1.a","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Use parallel structure.*","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.1.b","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Use various types of phrases (noun, verb, adjectival, adverbial, participial, prepositional, absolute) and clauses (independent, dependent; noun, relative, adverbial) to convey specific meanings and add variety and interest to writing or presentations.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.2","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.2.a","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Use a semicolon (and perhaps a conjunctive adverb) to link two or more closely related independent clauses.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.2.b","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Use a colon to introduce a list or quotation.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.2.c","grade":"9-10","strand":"L","section":"Conventions of Standard English:","description":"Spell correctly.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.3","grade":"9-10","strand":"L","section":"Knowledge of Language:","description":"Apply knowledge of language to understand how language functions in different contexts, to make effective choices for meaning or style, and to comprehend more fully when reading or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.3.a","grade":"9-10","strand":"L","section":"Knowledge of Language:","description":"Write and edit work so that it conforms to the guidelines in a style manual (e.g., MLA Handbook, Turabian's Manual for Writers) appropriate for the discipline and writing type.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.4","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grades 9-10 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.4.a","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., the overall meaning of a sentence, paragraph, or text; a word's position or function in a sentence) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.4.b","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify and correctly use patterns of word changes that indicate different meanings or parts of speech (e.g., analyze, analysis, analytical; advocate, advocacy).","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.4.c","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult general and specialized reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation of a word or determine or clarify its precise meaning, its part of speech, or its etymology.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.4.d","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Verify the preliminary determination of the meaning of a word or phrase (e.g., by checking the inferred meaning in context or in a dictionary).","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.5","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.5.a","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Interpret figures of speech (e.g., euphemism, oxymoron) in context and analyze their role in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.5.b","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Analyze nuances in the meaning of words with similar denotations.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"L.9-10.6","grade":"9-10","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately general academic and domain-specific words and phrases, sufficient for reading, writing, speaking, and listening at the college and career readiness level; demonstrate independence in gathering vocabulary knowledge when considering a word or phrase important to comprehension or expression.","source":"https://www.thecorestandards.org/ELA-Literacy/L/9-10/","applicable":true},{"code":"RL.11-12.10","grade":"11-12","strand":"RL","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.1","grade":"11-12","strand":"RL","section":"Key Ideas and Details:","description":"Cite strong and thorough textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text, including determining where the text leaves matters uncertain.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.2","grade":"11-12","strand":"RL","section":"Key Ideas and Details:","description":"Determine two or more themes or central ideas of a text and analyze their development over the course of the text, including how they interact and build on one another to produce a complex account; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.3","grade":"11-12","strand":"RL","section":"Key Ideas and Details:","description":"Analyze the impact of the author's choices regarding how to develop and relate elements of a story or drama (e.g., where a story is set, how the action is ordered, how the characters are introduced and developed).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.4","grade":"11-12","strand":"RL","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in the text, including figurative and connotative meanings; analyze the impact of specific word choices on meaning and tone, including words with multiple meanings or language that is particularly fresh, engaging, or beautiful. (Include Shakespeare as well as other authors.)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.5","grade":"11-12","strand":"RL","section":"Craft and Structure:","description":"Analyze how an author's choices concerning how to structure specific parts of a text (e.g., the choice of where to begin or end a story, the choice to provide a comedic or tragic resolution) contribute to its overall structure and meaning as well as its aesthetic impact.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.6","grade":"11-12","strand":"RL","section":"Craft and Structure:","description":"Analyze a case in which grasping a point of view requires distinguishing what is directly stated in a text from what is really meant (e.g., satire, sarcasm, irony, or understatement).","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.7","grade":"11-12","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Analyze multiple interpretations of a story, drama, or poem (e.g., recorded or live production of a play or recorded novel or poetry), evaluating how each version interprets the source text. (Include at least one play by Shakespeare and one play by an American dramatist.)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RL.11-12.8","grade":"11-12","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"(RL.11-12.8 not applicable to literature)","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":false},{"code":"RL.11-12.9","grade":"11-12","strand":"RL","section":"Integration of Knowledge and Ideas:","description":"Demonstrate knowledge of eighteenth-, nineteenth- and early-twentieth-century foundational works of American literature, including how two or more texts from the same period treat similar themes or topics.","source":"https://www.thecorestandards.org/ELA-Literacy/RL/11-12/","applicable":true},{"code":"RI.11-12.10","grade":"11-12","strand":"RI","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.1","grade":"11-12","strand":"RI","section":"Key Ideas and Details:","description":"Cite strong and thorough textual evidence to support analysis of what the text says explicitly as well as inferences drawn from the text, including determining where the text leaves matters uncertain.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.2","grade":"11-12","strand":"RI","section":"Key Ideas and Details:","description":"Determine two or more central ideas of a text and analyze their development over the course of the text, including how they interact and build on one another to provide a complex analysis; provide an objective summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.3","grade":"11-12","strand":"RI","section":"Key Ideas and Details:","description":"Analyze a complex set of ideas or sequence of events and explain how specific individuals, ideas, or events interact and develop over the course of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.4","grade":"11-12","strand":"RI","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including figurative, connotative, and technical meanings; analyze how an author uses and refines the meaning of a key term or terms over the course of a text (e.g., how Madison defines faction in Federalist No. 10).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.5","grade":"11-12","strand":"RI","section":"Craft and Structure:","description":"Analyze and evaluate the effectiveness of the structure an author uses in his or her exposition or argument, including whether the structure makes points clear, convincing, and engaging.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.6","grade":"11-12","strand":"RI","section":"Craft and Structure:","description":"Determine an author's point of view or purpose in a text in which the rhetoric is particularly effective, analyzing how style and content contribute to the power, persuasiveness or beauty of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.7","grade":"11-12","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Integrate and evaluate multiple sources of information presented in different media or formats (e.g., visually, quantitatively) as well as in words in order to address a question or solve a problem.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.8","grade":"11-12","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Delineate and evaluate the reasoning in seminal U.S. texts, including the application of constitutional principles and use of legal reasoning (e.g., in U.S. Supreme Court majority opinions and dissents) and the premises, purposes, and arguments in works of public advocacy (e.g., The Federalist, presidential addresses).","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"RI.11-12.9","grade":"11-12","strand":"RI","section":"Integration of Knowledge and Ideas:","description":"Analyze seventeenth-, eighteenth-, and nineteenth-century foundational U.S. documents of historical and literary significance (including The Declaration of Independence, the Preamble to the Constitution, the Bill of Rights, and Lincoln's Second Inaugural Address) for their themes, purposes, and rhetorical features.","source":"https://www.thecorestandards.org/ELA-Literacy/RI/11-12/","applicable":true},{"code":"W.11-12.10","grade":"11-12","strand":"W","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.1","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Write arguments to support claims in an analysis of substantive topics or texts, using valid reasoning and relevant and sufficient evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.1.a","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Introduce precise, knowledgeable claim(s), establish the significance of the claim(s), distinguish the claim(s) from alternate or opposing claims, and create an organization that logically sequences claim(s), counterclaims, reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.1.b","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Develop claim(s) and counterclaims fairly and thoroughly, supplying the most relevant evidence for each while pointing out the strengths and limitations of both in a manner that anticipates the audience's knowledge level, concerns, values, and possible biases.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.1.c","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses as well as varied syntax to link the major sections of the text, create cohesion, and clarify the relationships between claim(s) and reasons, between reasons and evidence, and between claim(s) and counterclaims.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.1.d","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.1.e","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Write informative/explanatory texts to examine and convey complex ideas, concepts, and information clearly and accurately through the effective selection, organization, and analysis of content.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2.a","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Introduce a topic; organize complex ideas, concepts, and information so that each new element builds on that which precedes it to create a unified whole; include formatting (e.g., headings), graphics (e.g., figures, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2.b","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Develop the topic thoroughly by selecting the most significant and relevant facts, extended definitions, concrete details, quotations, or other information and examples appropriate to the audience's knowledge of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2.c","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Use appropriate and varied transitions and syntax to link the major sections of the text, create cohesion, and clarify the relationships among complex ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2.d","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Use precise language, domain-specific vocabulary, and techniques such as metaphor, simile, and analogy to manage the complexity of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2.e","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.2.f","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation presented (e.g., articulating implications or the significance of the topic).","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.3","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Write narratives to develop real or imagined experiences or events using effective technique, well-chosen details, and well-structured event sequences.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.3.a","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Engage and orient the reader by setting out a problem, situation, or observation and its significance, establishing one or multiple point(s) of view, and introducing a narrator and/or characters; create a smooth progression of experiences or events.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.3.b","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Use narrative techniques, such as dialogue, pacing, description, reflection, and multiple plot lines, to develop experiences, events, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.3.c","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Use a variety of techniques to sequence events so that they build on one another to create a coherent whole and build toward a particular tone and outcome (e.g., a sense of mystery, suspense, growth, or resolution).","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.3.d","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Use precise words and phrases, telling details, and sensory language to convey a vivid picture of the experiences, events, setting, and/or characters.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.3.e","grade":"11-12","strand":"W","section":"Text Types and Purposes:","description":"Provide a conclusion that follows from and reflects on what is experienced, observed, or resolved over the course of the narrative.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.4","grade":"11-12","strand":"W","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience. (Grade-specific expectations for writing types are defined in standards 1-3 above.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.5","grade":"11-12","strand":"W","section":"Production and Distribution of Writing:","description":"Develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on addressing what is most significant for a specific purpose and audience. (Editing for conventions should demonstrate command of Language standards 1-3 up to and including grades 11-12 here.)","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.6","grade":"11-12","strand":"W","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce, publish, and update individual or shared writing products in response to ongoing feedback, including new arguments or information.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.7","grade":"11-12","strand":"W","section":"Research to Build and Present Knowledge:","description":"Conduct short as well as more sustained research projects to answer a question (including a self-generated question) or solve a problem; narrow or broaden the inquiry when appropriate; synthesize multiple sources on the subject, demonstrating understanding of the subject under investigation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.8","grade":"11-12","strand":"W","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple authoritative print and digital sources, using advanced searches effectively; assess the strengths and limitations of each source in terms of the task, purpose, and audience; integrate information into the text selectively to maintain the flow of ideas, avoiding plagiarism and overreliance on any one source and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.9","grade":"11-12","strand":"W","section":"Research to Build and Present Knowledge:","description":"Draw evidence from literary or informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.9.a","grade":"11-12","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grades 11-12 Reading standards to literature (e.g., \"Demonstrate knowledge of eighteenth-, nineteenth- and early-twentieth-century foundational works of American literature, including how two or more texts from the same period treat similar themes or topics\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"W.11-12.9.b","grade":"11-12","strand":"W","section":"Research to Build and Present Knowledge:","description":"Apply grades 11-12 Reading standards to literary nonfiction (e.g., \"Delineate and evaluate the reasoning in seminal U.S. texts, including the application of constitutional principles and use of legal reasoning [e.g., in U.S. Supreme Court Case majority opinions and dissents] and the premises, purposes, and arguments in works of public advocacy [e.g., The Federalist, presidential addresses]\").","source":"https://www.thecorestandards.org/ELA-Literacy/W/11-12/","applicable":true},{"code":"SL.11-12.6","grade":"11-12","strand":"SL","section":"Standards in this strand:","description":"The CCR anchor standards and high school grade-specific standards work in tandem to define college and career readiness expectations—the former providing broad standards, the latter providing additional specificity.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.1","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Initiate and participate effectively in a range of collaborative discussions (one-on-one, in groups, and teacher-led) with diverse partners on grades 11-12 topics, texts, and issues, building on others' ideas and expressing their own clearly and persuasively.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.1.a","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Come to discussions prepared, having read and researched material under study; explicitly draw on that preparation by referring to evidence from texts and other research on the topic or issue to stimulate a thoughtful, well-reasoned exchange of ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.1.b","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Work with peers to promote civil, democratic discussions and decision-making, set clear goals and deadlines, and establish individual roles as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.1.c","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Propel conversations by posing and responding to questions that probe reasoning and evidence; ensure a hearing for a full range of positions on a topic or issue; clarify, verify, or challenge ideas and conclusions; and promote divergent and creative perspectives.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.1.d","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Respond thoughtfully to diverse perspectives; synthesize comments, claims, and evidence made on all sides of an issue; resolve contradictions when possible; and determine what additional information or research is required to deepen the investigation or complete the task.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.2","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Integrate multiple sources of information presented in diverse formats and media (e.g., visually, quantitatively, orally) in order to make informed decisions and solve problems, evaluating the credibility and accuracy of each source and noting any discrepancies among the data.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.3","grade":"11-12","strand":"SL","section":"Comprehension and Collaboration:","description":"Evaluate a speaker's point of view, reasoning, and use of evidence and rhetoric, assessing the stance, premises, links among ideas, word choice, points of emphasis, and tone used.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.4","grade":"11-12","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Present information, findings, and supporting evidence, conveying a clear and distinct perspective, such that listeners can follow the line of reasoning, alternative or opposing perspectives are addressed, and the organization, development, substance, and style are appropriate to purpose, audience, and a range of formal and informal tasks.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"SL.11-12.5","grade":"11-12","strand":"SL","section":"Presentation of Knowledge and Ideas:","description":"Make strategic use of digital media (e.g., textual, graphical, audio, visual, and interactive elements) in presentations to enhance understanding of findings, reasoning, and evidence and to add interest.","source":"https://www.thecorestandards.org/ELA-Literacy/SL/11-12/","applicable":true},{"code":"L.11-12.1","grade":"11-12","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English grammar and usage when writing or speaking.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.1.a","grade":"11-12","strand":"L","section":"Conventions of Standard English:","description":"Apply the understanding that usage is a matter of convention, can change over time, and is sometimes contested.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.1.b","grade":"11-12","strand":"L","section":"Conventions of Standard English:","description":"Resolve issues of complex or contested usage, consulting references (e.g., Merriam-Webster's Dictionary of English Usage, Garner's Modern American Usage) as needed.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.2","grade":"11-12","strand":"L","section":"Conventions of Standard English:","description":"Demonstrate command of the conventions of standard English capitalization, punctuation, and spelling when writing.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.2.a","grade":"11-12","strand":"L","section":"Conventions of Standard English:","description":"Observe hyphenation conventions.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.2.b","grade":"11-12","strand":"L","section":"Conventions of Standard English:","description":"Spell correctly.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.3","grade":"11-12","strand":"L","section":"Knowledge of Language:","description":"Apply knowledge of language to understand how language functions in different contexts, to make effective choices for meaning or style, and to comprehend more fully when reading or listening.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.3.a","grade":"11-12","strand":"L","section":"Knowledge of Language:","description":"Vary syntax for effect, consulting references (e.g., Tufte's Artful Sentences) for guidance as needed; apply an understanding of syntax to the study of complex texts when reading.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.4","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Determine or clarify the meaning of unknown and multiple-meaning words and phrases based on grades 11-12 reading and content, choosing flexibly from a range of strategies.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.4.a","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Use context (e.g., the overall meaning of a sentence, paragraph, or text; a word's position or function in a sentence) as a clue to the meaning of a word or phrase.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.4.b","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Identify and correctly use patterns of word changes that indicate different meanings or parts of speech (e.g., conceive, conception, conceivable).","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.4.c","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Consult general and specialized reference materials (e.g., dictionaries, glossaries, thesauruses), both print and digital, to find the pronunciation of a word or determine or clarify its precise meaning, its part of speech, its etymology, or its standard usage.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.4.d","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Verify the preliminary determination of the meaning of a word or phrase (e.g., by checking the inferred meaning in context or in a dictionary).","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.5","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Demonstrate understanding of figurative language, word relationships, and nuances in word meanings.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.5.a","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Interpret figures of speech (e.g., hyperbole, paradox) in context and analyze their role in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.5.b","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Analyze nuances in the meaning of words with similar denotations.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"L.11-12.6","grade":"11-12","strand":"L","section":"Vocabulary Acquisition and Use:","description":"Acquire and use accurately general academic and domain-specific words and phrases, sufficient for reading, writing, speaking, and listening at the college and career readiness level; demonstrate independence in gathering vocabulary knowledge when considering a word or phrase important to comprehension or expression.","source":"https://www.thecorestandards.org/ELA-Literacy/L/11-12/","applicable":true},{"code":"RH.6-8.1","grade":"6-8","strand":"RH","section":"Key Ideas and Details:","description":"Cite specific textual evidence to support analysis of primary and secondary sources.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.2","grade":"6-8","strand":"RH","section":"Key Ideas and Details:","description":"Determine the central ideas or information of a primary or secondary source; provide an accurate summary of the source distinct from prior knowledge or opinions.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.3","grade":"6-8","strand":"RH","section":"Key Ideas and Details:","description":"Identify key steps in a text's description of a process related to history/social studies (e.g., how a bill becomes law, how interest rates are raised or lowered).","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.4","grade":"6-8","strand":"RH","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including vocabulary specific to domains related to history/social studies.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.5","grade":"6-8","strand":"RH","section":"Craft and Structure:","description":"Describe how a text presents information (e.g., sequentially, comparatively, causally).","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.6","grade":"6-8","strand":"RH","section":"Craft and Structure:","description":"Identify aspects of a text that reveal an author's point of view or purpose (e.g., loaded language, inclusion or avoidance of particular facts).","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.7","grade":"6-8","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Integrate visual information (e.g., in charts, graphs, photographs, videos, or maps) with other information in print and digital texts.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.8","grade":"6-8","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Distinguish among fact, opinion, and reasoned judgment in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.9","grade":"6-8","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Analyze the relationship between a primary and secondary source on the same topic.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.6-8.10","grade":"6-8","strand":"RH","section":"Range of Reading and Level of Text Complexity:","description":"By the end of grade 8, read and comprehend history/social studies texts in the grades 6-8 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/6-8/","applicable":true},{"code":"RH.9-10.1","grade":"9-10","strand":"RH","section":"Key Ideas and Details:","description":"Cite specific textual evidence to support analysis of primary and secondary sources, attending to such features as the date and origin of the information.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.2","grade":"9-10","strand":"RH","section":"Key Ideas and Details:","description":"Determine the central ideas or information of a primary or secondary source; provide an accurate summary of how key events or ideas develop over the course of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.3","grade":"9-10","strand":"RH","section":"Key Ideas and Details:","description":"Analyze in detail a series of events described in a text; determine whether earlier events caused later ones or simply preceded them.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.4","grade":"9-10","strand":"RH","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including vocabulary describing political, social, or economic aspects of history/social science.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.5","grade":"9-10","strand":"RH","section":"Craft and Structure:","description":"Analyze how a text uses structure to emphasize key points or advance an explanation or analysis.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.6","grade":"9-10","strand":"RH","section":"Craft and Structure:","description":"Compare the point of view of two or more authors for how they treat the same or similar topics, including which details they include and emphasize in their respective accounts.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.7","grade":"9-10","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Integrate quantitative or technical analysis (e.g., charts, research data) with qualitative analysis in print or digital text.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.8","grade":"9-10","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Assess the extent to which the reasoning and evidence in a text support the author's claims.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.9","grade":"9-10","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast treatments of the same topic in several primary and secondary sources.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.9-10.10","grade":"9-10","strand":"RH","section":"Range of Reading and Level of Text Complexity:","description":"By the end of grade 10, read and comprehend history/social studies texts in the grades 9-10 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/9-10/","applicable":true},{"code":"RH.11-12.1","grade":"11-12","strand":"RH","section":"Key Ideas and Details:","description":"Cite specific textual evidence to support analysis of primary and secondary sources, connecting insights gained from specific details to an understanding of the text as a whole.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.2","grade":"11-12","strand":"RH","section":"Key Ideas and Details:","description":"Determine the central ideas or information of a primary or secondary source; provide an accurate summary that makes clear the relationships among the key details and ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.3","grade":"11-12","strand":"RH","section":"Key Ideas and Details:","description":"Evaluate various explanations for actions or events and determine which explanation best accords with textual evidence, acknowledging where the text leaves matters uncertain.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.4","grade":"11-12","strand":"RH","section":"Craft and Structure:","description":"Determine the meaning of words and phrases as they are used in a text, including analyzing how an author uses and refines the meaning of a key term over the course of a text (e.g., how Madison defines faction in Federalist No. 10).","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.5","grade":"11-12","strand":"RH","section":"Craft and Structure:","description":"Analyze in detail how a complex primary source is structured, including how key sentences, paragraphs, and larger portions of the text contribute to the whole.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.6","grade":"11-12","strand":"RH","section":"Craft and Structure:","description":"Evaluate authors' differing points of view on the same historical event or issue by assessing the authors' claims, reasoning, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.7","grade":"11-12","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Integrate and evaluate multiple sources of information presented in diverse formats and media (e.g., visually, quantitatively, as well as in words) in order to address a question or solve a problem.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.8","grade":"11-12","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Evaluate an author's premises, claims, and evidence by corroborating or challenging them with other information.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.9","grade":"11-12","strand":"RH","section":"Integration of Knowledge and Ideas:","description":"Integrate information from diverse sources, both primary and secondary, into a coherent understanding of an idea or event, noting discrepancies among sources.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RH.11-12.10","grade":"11-12","strand":"RH","section":"Range of Reading and Level of Text Complexity:","description":"By the end of grade 12, read and comprehend history/social studies texts in the grades 11-CCR text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RH/11-12/","applicable":true},{"code":"RST.6-8.1","grade":"6-8","strand":"RST","section":"Key Ideas and Details:","description":"Cite specific textual evidence to support analysis of science and technical texts.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.2","grade":"6-8","strand":"RST","section":"Key Ideas and Details:","description":"Determine the central ideas or conclusions of a text; provide an accurate summary of the text distinct from prior knowledge or opinions.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.3","grade":"6-8","strand":"RST","section":"Key Ideas and Details:","description":"Follow precisely a multistep procedure when carrying out experiments, taking measurements, or performing technical tasks.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.4","grade":"6-8","strand":"RST","section":"Craft and Structure:","description":"Determine the meaning of symbols, key terms, and other domain-specific words and phrases as they are used in a specific scientific or technical context relevant to grades 6-8 texts and topics.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.5","grade":"6-8","strand":"RST","section":"Craft and Structure:","description":"Analyze the structure an author uses to organize a text, including how the major sections contribute to the whole and to an understanding of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.6","grade":"6-8","strand":"RST","section":"Craft and Structure:","description":"Analyze the author's purpose in providing an explanation, describing a procedure, or discussing an experiment in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.7","grade":"6-8","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Integrate quantitative or technical information expressed in words in a text with a version of that information expressed visually (e.g., in a flowchart, diagram, model, graph, or table).","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.8","grade":"6-8","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Distinguish among facts, reasoned judgment based on research findings, and speculation in a text.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.9","grade":"6-8","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast the information gained from experiments, simulations, video, or multimedia sources with that gained from reading a text on the same topic.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.6-8.10","grade":"6-8","strand":"RST","section":"Range of Reading and Level of Text Complexity:","description":"By the end of grade 8, read and comprehend science/technical texts in the grades 6-8 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/6-8/","applicable":true},{"code":"RST.9-10.1","grade":"9-10","strand":"RST","section":"Key Ideas and Details:","description":"Cite specific textual evidence to support analysis of science and technical texts, attending to the precise details of explanations or descriptions.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.2","grade":"9-10","strand":"RST","section":"Key Ideas and Details:","description":"Determine the central ideas or conclusions of a text; trace the text's explanation or depiction of a complex process, phenomenon, or concept; provide an accurate summary of the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.3","grade":"9-10","strand":"RST","section":"Key Ideas and Details:","description":"Follow precisely a complex multistep procedure when carrying out experiments, taking measurements, or performing technical tasks, attending to special cases or exceptions defined in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.4","grade":"9-10","strand":"RST","section":"Craft and Structure:","description":"Determine the meaning of symbols, key terms, and other domain-specific words and phrases as they are used in a specific scientific or technical context relevant to grades 9-10 texts and topics.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.5","grade":"9-10","strand":"RST","section":"Craft and Structure:","description":"Analyze the structure of the relationships among concepts in a text, including relationships among key terms (e.g., force, friction, reaction force, energy).","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.6","grade":"9-10","strand":"RST","section":"Craft and Structure:","description":"Analyze the author's purpose in providing an explanation, describing a procedure, or discussing an experiment in a text, defining the question the author seeks to address.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.7","grade":"9-10","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Translate quantitative or technical information expressed in words in a text into visual form (e.g., a table or chart) and translate information expressed visually or mathematically (e.g., in an equation) into words.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.8","grade":"9-10","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Assess the extent to which the reasoning and evidence in a text support the author's claim or a recommendation for solving a scientific or technical problem.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.9","grade":"9-10","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Compare and contrast findings presented in a text to those from other sources (including their own experiments), noting when the findings support or contradict previous explanations or accounts.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.9-10.10","grade":"9-10","strand":"RST","section":"Range of Reading and Level of Text Complexity:","description":"By the end of grade 10, read and comprehend science/technical texts in the grades 9-10 text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/9-10/","applicable":true},{"code":"RST.11-12.1","grade":"11-12","strand":"RST","section":"Key Ideas and Details:","description":"Cite specific textual evidence to support analysis of science and technical texts, attending to important distinctions the author makes and to any gaps or inconsistencies in the account.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.2","grade":"11-12","strand":"RST","section":"Key Ideas and Details:","description":"Determine the central ideas or conclusions of a text; summarize complex concepts, processes, or information presented in a text by paraphrasing them in simpler but still accurate terms.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.3","grade":"11-12","strand":"RST","section":"Key Ideas and Details:","description":"Follow precisely a complex multistep procedure when carrying out experiments, taking measurements, or performing technical tasks; analyze the specific results based on explanations in the text.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.4","grade":"11-12","strand":"RST","section":"Craft and Structure:","description":"Determine the meaning of symbols, key terms, and other domain-specific words and phrases as they are used in a specific scientific or technical context relevant to grades 11-12 texts and topics.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.5","grade":"11-12","strand":"RST","section":"Craft and Structure:","description":"Analyze how the text structures information or ideas into categories or hierarchies, demonstrating understanding of the information or ideas.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.6","grade":"11-12","strand":"RST","section":"Craft and Structure:","description":"Analyze the author's purpose in providing an explanation, describing a procedure, or discussing an experiment in a text, identifying important issues that remain unresolved.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.7","grade":"11-12","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Integrate and evaluate multiple sources of information presented in diverse formats and media (e.g., quantitative data, video, multimedia) in order to address a question or solve a problem.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.8","grade":"11-12","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Evaluate the hypotheses, data, analysis, and conclusions in a science or technical text, verifying the data when possible and corroborating or challenging conclusions with other sources of information.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.9","grade":"11-12","strand":"RST","section":"Integration of Knowledge and Ideas:","description":"Synthesize information from a range of sources (e.g., texts, experiments, simulations) into a coherent understanding of a process, phenomenon, or concept, resolving conflicting information when possible.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"RST.11-12.10","grade":"11-12","strand":"RST","section":"Range of Reading and Level of Text Complexity:","description":"By the end of grade 12, read and comprehend science/technical texts in the grades 11-CCR text complexity band independently and proficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/RST/11-12/","applicable":true},{"code":"WHST.6-8.1","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Write arguments focused on discipline-specific content.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.1.a","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Introduce claim(s) about a topic or issue, acknowledge and distinguish the claim(s) from alternate or opposing claims, and organize the reasons and evidence logically.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.1.b","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Support claim(s) with logical reasoning and relevant, accurate data and evidence that demonstrate an understanding of the topic or text, using credible sources.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.1.c","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses to create cohesion and clarify the relationships among claim(s), counterclaims, reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.1.d","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Establish and maintain a formal style.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.1.e","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Write informative/explanatory texts, including the narration of historical events, scientific procedures/ experiments, or technical processes.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2.a","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Introduce a topic clearly, previewing what is to follow; organize ideas, concepts, and information into broader categories as appropriate to achieving purpose; include formatting (e.g., headings), graphics (e.g., charts, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2.b","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Develop the topic with relevant, well-chosen facts, definitions, concrete details, quotations, or other information and examples.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2.c","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Use appropriate and varied transitions to create cohesion and clarify the relationships among ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2.d","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to inform about or explain the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2.e","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.2.f","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation presented.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.3","grade":"6-8","strand":"WHST","section":"Text Types and Purposes:","description":"(See note; not applicable as a separate requirement)","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.4","grade":"6-8","strand":"WHST","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.5","grade":"6-8","strand":"WHST","section":"Production and Distribution of Writing:","description":"With some guidance and support from peers and adults, develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on how well purpose and audience have been addressed.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.6","grade":"6-8","strand":"WHST","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce and publish writing and present the relationships between information and ideas clearly and efficiently.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.7","grade":"6-8","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Conduct short research projects to answer a question (including a self-generated question), drawing on several sources and generating additional related, focused questions that allow for multiple avenues of exploration.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.8","grade":"6-8","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple print and digital sources, using search terms effectively; assess the credibility and accuracy of each source; and quote or paraphrase the data and conclusions of others while avoiding plagiarism and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.9","grade":"6-8","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Draw evidence from informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.6-8.10","grade":"6-8","strand":"WHST","section":"Range of Writing:","description":"Write routinely over extended time frames (time for reflection and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/6-8/","applicable":true},{"code":"WHST.9-10.1","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Write arguments focused on discipline-specific content.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.1.a","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Introduce precise claim(s), distinguish the claim(s) from alternate or opposing claims, and create an organization that establishes clear relationships among the claim(s), counterclaims, reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.1.b","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Develop claim(s) and counterclaims fairly, supplying data and evidence for each while pointing out the strengths and limitations of both claim(s) and counterclaims in a discipline-appropriate form and in a manner that anticipates the audience's knowledge level and concerns.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.1.c","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses to link the major sections of the text, create cohesion, and clarify the relationships between claim(s) and reasons, between reasons and evidence, and between claim(s) and counterclaims.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.1.d","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.1.e","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from or supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Write informative/explanatory texts, including the narration of historical events, scientific procedures/ experiments, or technical processes.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2.a","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Introduce a topic and organize ideas, concepts, and information to make important connections and distinctions; include formatting (e.g., headings), graphics (e.g., figures, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2.b","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Develop the topic with well-chosen, relevant, and sufficient facts, extended definitions, concrete details, quotations, or other information and examples appropriate to the audience's knowledge of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2.c","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Use varied transitions and sentence structures to link the major sections of the text, create cohesion, and clarify the relationships among ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2.d","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Use precise language and domain-specific vocabulary to manage the complexity of the topic and convey a style appropriate to the discipline and context as well as to the expertise of likely readers.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2.e","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.2.f","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation presented (e.g., articulating implications or the significance of the topic).","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.3","grade":"9-10","strand":"WHST","section":"Text Types and Purposes:","description":"(See note; not applicable as a separate requirement)","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.4","grade":"9-10","strand":"WHST","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.5","grade":"9-10","strand":"WHST","section":"Production and Distribution of Writing:","description":"Develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on addressing what is most significant for a specific purpose and audience.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.6","grade":"9-10","strand":"WHST","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce, publish, and update individual or shared writing products, taking advantage of technology's capacity to link to other information and to display information flexibly and dynamically.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.7","grade":"9-10","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Conduct short as well as more sustained research projects to answer a question (including a self-generated question) or solve a problem; narrow or broaden the inquiry when appropriate; synthesize multiple sources on the subject, demonstrating understanding of the subject under investigation.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.8","grade":"9-10","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple authoritative print and digital sources, using advanced searches effectively; assess the usefulness of each source in answering the research question; integrate information into the text selectively to maintain the flow of ideas, avoiding plagiarism and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.9","grade":"9-10","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Draw evidence from informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.9-10.10","grade":"9-10","strand":"WHST","section":"Range of Writing:","description":"Write routinely over extended time frames (time for reflection and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/9-10/","applicable":true},{"code":"WHST.11-12.1","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Write arguments focused on discipline-specific content.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.1.a","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Introduce precise, knowledgeable claim(s), establish the significance of the claim(s), distinguish the claim(s) from alternate or opposing claims, and create an organization that logically sequences the claim(s), counterclaims, reasons, and evidence.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.1.b","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Develop claim(s) and counterclaims fairly and thoroughly, supplying the most relevant data and evidence for each while pointing out the strengths and limitations of both claim(s) and counterclaims in a discipline-appropriate form that anticipates the audience's knowledge level, concerns, values, and possible biases.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.1.c","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Use words, phrases, and clauses as well as varied syntax to link the major sections of the text, create cohesion, and clarify the relationships between claim(s) and reasons, between reasons and evidence, and between claim(s) and counterclaims.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.1.d","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Establish and maintain a formal style and objective tone while attending to the norms and conventions of the discipline in which they are writing.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.1.e","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from or supports the argument presented.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.2","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Write informative/explanatory texts, including the narration of historical events, scientific procedures/experiments, or technical processes.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.2.a","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Introduce a topic and organize complex ideas, concepts, and information so that each new element builds on that which precedes it to create a unified whole; include formatting (e.g., headings), graphics (e.g., figures, tables), and multimedia when useful to aiding comprehension.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.2.b","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Develop the topic thoroughly by selecting the most significant and relevant facts, extended definitions, concrete details, quotations, or other information and examples appropriate to the audience's knowledge of the topic.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.2.c","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Use varied transitions and sentence structures to link the major sections of the text, create cohesion, and clarify the relationships among complex ideas and concepts.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.2.d","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Use precise language, domain-specific vocabulary and techniques such as metaphor, simile, and analogy to manage the complexity of the topic; convey a knowledgeable stance in a style that responds to the discipline and context as well as to the expertise of likely readers.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.2.e","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"Provide a concluding statement or section that follows from and supports the information or explanation provided (e.g., articulating implications or the significance of the topic).","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.3","grade":"11-12","strand":"WHST","section":"Text Types and Purposes:","description":"(See note; not applicable as a separate requirement)","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.4","grade":"11-12","strand":"WHST","section":"Production and Distribution of Writing:","description":"Produce clear and coherent writing in which the development, organization, and style are appropriate to task, purpose, and audience.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.5","grade":"11-12","strand":"WHST","section":"Production and Distribution of Writing:","description":"Develop and strengthen writing as needed by planning, revising, editing, rewriting, or trying a new approach, focusing on addressing what is most significant for a specific purpose and audience.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.6","grade":"11-12","strand":"WHST","section":"Production and Distribution of Writing:","description":"Use technology, including the Internet, to produce, publish, and update individual or shared writing products in response to ongoing feedback, including new arguments or information.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.7","grade":"11-12","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Conduct short as well as more sustained research projects to answer a question (including a self-generated question) or solve a problem; narrow or broaden the inquiry when appropriate; synthesize multiple sources on the subject, demonstrating understanding of the subject under investigation.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.8","grade":"11-12","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Gather relevant information from multiple authoritative print and digital sources, using advanced searches effectively; assess the strengths and limitations of each source in terms of the specific task, purpose, and audience; integrate information into the text selectively to maintain the flow of ideas, avoiding plagiarism and overreliance on any one source and following a standard format for citation.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.9","grade":"11-12","strand":"WHST","section":"Research to Build and Present Knowledge:","description":"Draw evidence from informational texts to support analysis, reflection, and research.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true},{"code":"WHST.11-12.10","grade":"11-12","strand":"WHST","section":"Range of Writing:","description":"Write routinely over extended time frames (time for reflection and revision) and shorter time frames (a single sitting or a day or two) for a range of discipline-specific tasks, purposes, and audiences.","source":"https://www.thecorestandards.org/ELA-Literacy/WHST/11-12/","applicable":true}]};
